function loadStore(){const base={completed:[],favorites:[],quizBest:0,streak:0,lastVisit:'',tipsSeen:0,notes:{},settings:{}};try{const data=JSON.parse(localStorage.getItem(KEY)||'{}');if(!data||typeof data!=='object'||Array.isArray(data))return base;const finiteInt=(v,fallback,max)=>Number.isFinite(Number(v))?Math.max(0,Math.min(max,Math.floor(Number(v)))):fallback;const validDate=v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(Date.parse(`${v}T00:00:00Z`))&&new Date(`${v}T00:00:00Z`).toISOString().slice(0,10)===v;const notes=data.notes&&typeof data.notes==='object'&&!Array.isArray(data.notes)?Object.fromEntries(Object.entries(data.notes).slice(0,200).filter(([k,v])=>typeof k==='string'&&typeof v==='string').map(([k,v])=>[k.slice(0,120),v.slice(0,3000)])):{};return{completed:Array.isArray(data.completed)?[...new Set(data.completed.filter(x=>typeof x==='string'&&/^[a-zA-Z0-9_-]{1,40}$/.test(x)).slice(0,100))]:[],favorites:Array.isArray(data.favorites)?[...new Set(data.favorites.filter(x=>typeof x==='string'&&x.length<=100).slice(0,200))]:[],quizBest:finiteInt(data.quizBest,0,10),streak:finiteInt(data.streak,0,10000),lastVisit:validDate(data.lastVisit)?data.lastVisit:'',tipsSeen:finiteInt(data.tipsSeen,0,1000000),notes,settings:{}}}catch{return base}}
function save(){try{localStorage.setItem(KEY,JSON.stringify(store));return true}catch{try{if($('#toast'))toast('Browser storage is unavailable or full; this change may not persist')}catch{}return false}}
const day=new Date(); const dateKey=day.toISOString().slice(0,10); if(store.lastVisit!==dateKey){const prev=new Date();prev.setDate(prev.getDate()-1);store.streak=store.lastVisit===prev.toISOString().slice(0,10)?(store.streak||0)+1:1;store.lastVisit=dateKey;save()}
const tips=["Taste before you garnish. The last few drops of citrus or bitters can change a drink's balance more than another ounce of spirit.","A chilled glass is an ingredient: it slows dilution and keeps a short drink composed from first sip to last.","Use fresh citrus, then taste. Fruit acidity changes by season; recipes are starting points, not laws.","For a stirred drink, aim for cold, controlled dilution. Listen for the sound to soften and watch the mixing glass frost.","Hospitality starts with a clear welcome and an unhurried question: ‘What do you usually enjoy?’","Keep your station mise en place tidy: label, date, rotate, and put every tool back in its home.","A garnish should signal aroma, add an edible accent, or reinforce the drink's story. If it does none of these, simplify.","Build highballs over fresh, hard ice; add the carbonated mixer last and lift once gently to preserve sparkle.","Describe flavors in familiar language before using technical terms. ‘Bright and tart’ is more useful than ‘high acid’ for many guests.","Measure consistently. Precision protects balance, cost control, and responsible service."];
