const knownNames=new Set(Object.keys(known));
function inferSpirit(name,i){if(known[name])return known[name][0];const n=name.toLowerCase();for(const [key,words] of Object.entries({tequila:['margarita','paloma','tequila','batanga','vampiro','mexican','rosita'],mezcal:['mezcal'],rum:['rum','mai tai','mojito','daiquiri','punch','piña','zombie','hurricane','painkiller','swizzle','jungle','colada','cuba libre','dark','stormy','caipirinha'],whiskey:['whiskey','whisky','bourbon','rye','manhattan','old pal','rob roy','sazerac','penicillin','lion','toronto','tipperary','irish','toddy','julep'],gin:['gin','martini','negroni','southside','aviation','bramble','last word','white lady','corpse','vesper','pimm','bamboo','hanky','panky','tuxedo'],vodka:['vodka','cosmo','moscow','sea breeze','white russian','black russian','espresso martini','lemon drop','bloody mary'],brandy:['brandy','sidecar','pisco','jack rose','calvados','alexander','between the sheets','vieux carré'],wine:['bellini','mimosa','spritz','kir','champagne','sangria'],beer:['michelada']})){if(words.some(w=>n.includes(w)))return key}return spiritCycle[i%spiritCycle.length]}
function familyOf(name,i){if(known[name])return known[name][1];let n=name.toLowerCase();if(/sour|daisy|margarita|gimlet|daiquiri|sidecar|cosmo/.test(n))return 'sour';if(/martini|manhattan|old fashioned|sazerac|rob roy|rusty nail|boulevardier/.test(n))return 'spirit-forward';if(/mule|collins|rickey|tonic|highball|cuba libre|paloma/.test(n))return 'highball';if(/spritz|americano|negroni|boulevardier|bitter/.test(n))return 'bitter aperitivo';if(/punch|zombie|mai tai|colada|hurricane|tropical|bird|grog/.test(n))return 'tropical';if(/fizz|75|mimosa|bellini|royale/.test(n))return 'sparkling';return families[i%families.length]}
const genericSpecs={sour:'60 ml base spirit; 25 ml fresh citrus; 20 ml simple syrup', 'spirit-forward':'60 ml base spirit; 30 ml fortified wine or modifier; 2 dashes bitters','highball':'45 ml base spirit; 15 ml citrus; 100–120 ml sparkling mixer','bitter aperitivo':'30 ml base spirit; 30 ml bitter aperitivo; 30 ml vermouth or wine','tropical':'45 ml base spirit; 30 ml citrus; 60 ml tropical juice; 15 ml sweetener','sparkling':'30 ml base spirit or liqueur; 15 ml citrus; 90 ml sparkling wine','fizz':'45 ml base spirit; 20 ml citrus; 15 ml syrup; top soda','equal-parts sour':'22.5 ml each base spirit, modifier, sweet liqueur and citrus','modern classic':'45 ml base spirit; 22.5 ml citrus; 15–22.5 ml sweetener or modifier'};
const methodFor=f=>({sour:'Shake with ice; fine-strain into a chilled coupe or over fresh ice.', 'spirit-forward':'Stir with ice until cold; strain into a chilled coupe or over a large cube.',highball:'Build over fresh ice in a tall glass; top with chilled mixer and lift gently once.', 'bitter aperitivo':'Stir over ice or build over a large cube; express a citrus peel.',tropical:'Shake with ice and strain over fresh ice or crushed ice; garnish with fresh fruit.',sparkling:'Shake non-carbonated ingredients; strain into a flute or wine glass and top gently.',fizz:'Shake with ice; strain into a chilled glass and top with soda.', 'equal-parts sour':'Shake hard with ice; fine-strain into a chilled coupe.','modern classic':'Shake or stir according to the citrus content; serve cold with a purposeful garnish.'}[f]);
const profileFor=f=>({sour:'Bright acidity balanced by sweetness; the base spirit remains recognizable.', 'spirit-forward':'Aromatic, spirit-led and structured by bitters or fortified wine.',highball:'Long, refreshing and sparkling; dilution and temperature matter.', 'bitter aperitivo':'Bittersweet, herbal and citrus-accented, with a long finish.',tropical:'Juicy, textured and fruit-forward; acidity keeps sweetness lively.',sparkling:'Lifted, dry to gently sweet, with bubbles carrying the aroma.',fizz:'Light, lively and refreshing with a soft citrus spine.', 'equal-parts sour':'Taut, complex and layered; herbal sweetness meets fresh citrus.', 'modern classic':'Contemporary balance of a clear base spirit, bright acidity and a distinctive modifier.'}[f]);
function historyFor(name,f){if(known[name])return known[name][5];return `A recognized drink name in the modern cocktail canon. Exact first-creation details are not consistently documented; treat origin claims as lore unless supported by a contemporary source. Its structure is best understood through the ${f} family and the ingredients in the glass.`}
const cocktails=cocktailNames.map((name,i)=>{let s=inferSpirit(name,i), f=familyOf(name,i), b=bases[s]||['Spirit','spirit'];let k=known[name];return {name,spirit:s,base:b[0],family:f,spec:k?k[2]:genericSpecs[f].replace('base spirit',b[0].toLowerCase()),method:k?k[3]:methodFor(f),taste:k?k[4]:profileFor(f),history:k?k[5]:historyFor(name,f),origin:k?`Historical record: ${k[5].split('.')[0]}.`:'Origin: debated or insufficiently documented; avoid presenting a single origin legend as settled fact.',glass:/highball|mule|collins|punch|fizz|spritz|sling|julep|punch|colada|zombie/i.test(name)?'Highball / Collins':(/martini|sour|aviation|sidecar|last word|cosmo|75|crusta/i.test(name)?'Coupe / cocktail':'Rocks / old fashioned'), garnish:/gin|vodka|tequila|rum|brandy|whiskey|whisky|cachaça|pisco|mezcal/i.test(b[0])?'Citrus peel or ingredient-led garnish':'Citrus or herb garnish',rank:i+1}});
// Add well-known classics if a source list contained a name not already present; maintain exactly 200 cards.
const extras=['Army & Navy','Bamboo','Brooklyn','Daisy','Gin Rickey','Horses Neck','Improved Whiskey Cocktail','Japanese Cocktail','John Collins','Martinez','Pegu Club','Queen’s Park Swizzle','Scofflaw','Tuxedo','Ward Eight','White Lady','Yellow Bird','Zombie','Adonis','Brandy Crusta','El Presidente','Planter’s Punch','Sherry Cobbler','Southside','Tom Collins','Vesper'];
for(const n of extras){if(cocktails.length>=200)break;if(!cocktails.some(c=>c.name.toLowerCase()===n.toLowerCase())){let i=cocktails.length,s=inferSpirit(n,i),f=familyOf(n,i),b=bases[s]||['Spirit'];cocktails.push({name:n,spirit:s,base:b[0],family:f,spec:genericSpecs[f].replace('base spirit',b[0].toLowerCase()),method:methodFor(f),taste:profileFor(f),history:historyFor(n,f),origin:'Origin: contested or not firmly documented.',glass:'Coupe / rocks',garnish:'Citrus peel',rank:i+1})}}
// Guarantee stable 200-entry library if the curated input grows later.
while(cocktails.length<200){let i=cocktails.length,n=`Classic House Variation ${i-199}`,s=spiritCycle[i%spiritCycle.length],f=families[i%families.length],b=bases[s][0];cocktails.push({name:n,spirit:s,base:b,family:f,spec:genericSpecs[f].replace('base spirit',b.toLowerCase()),method:methodFor(f),taste:profileFor(f),history:'A useful training variation rather than a claim of a canonical historical recipe. Compare it with the named family template and adjust to taste.',origin:'Training variation; no single historic origin claimed.',glass:'Rocks / coupe',garnish:'Ingredient-led garnish',rank:i+1})}
const cocktailSourceMap=new Map((window.pourfolioCocktailCatalog||[]).map(x=>[x.name,x]));
cocktails.forEach(c=>{const src=cocktailSourceMap.get(c.name);if(!src)return;c.base=src.base||c.base;c.spirit=src.spirit||c.spirit;c.family=src.family||c.family;c.spec=src.spec||c.spec;c.method=src.method||c.method;c.glass=src.glass||c.glass;c.garnish=src.garnish||c.garnish;c.source=src.source||'Pourfolio study guide';c.recipeReference=src.recipeReference||'';c.fromSource=true;if(!known[c.name]){c.taste=src.taste||c.taste;c.history=src.history||c.history;c.origin=src.origin||c.origin}});
