const namedLiqueurProfiles={
'Amaretto':'Sweet almond and stone-fruit-kernel aroma, marzipan, vanilla and a gentle bitter finish.','Aperol':'Bittersweet orange, rhubarb-like root and soft herbs; lighter bitterness than many amari.','Campari':'Pronounced bitter orange, aromatic roots and herbs with a long, vivid bitter finish.','Cointreau':'Clear, dry orange-peel liqueur with bright citrus oil and a clean, dry-sweet finish.','Grand Marnier':'Orange zest over Cognac-like grape spirit, vanilla and warming oak.','Chartreuse, green':'Powerful alpine herbs, mint, spice and honey with high intensity and a long finish.','Chartreuse, yellow':'Softer floral herbs, honey, saffron-like spice and gentler sweetness.','Benedictine DOM':'Honeyed herbs, baking spice and citrus peel; rich but complex.','D.O.M. Bénédictine':'Honeyed herbs, baking spice and citrus peel; rich but complex.','Drambuie':'Scotch malt, heather honey, herbs and warm spice.','Fernet-Branca':'Intensely bitter mint, roots, saffron-like spice and medicinal herbs; assertive and dry.','Jägermeister':'Sweet-bitter herbs, citrus peel, anise and baking spice with a rounded finish.','Frangelico':'Toasted hazelnut, cocoa, vanilla and caramel; dessert-like and nutty.','Kahlúa':'Roasted coffee, caramel and vanilla with a dark, sweet finish.','Tia Maria':'Coffee, vanilla and Jamaican rum notes; roasted and gently spiced.','Limoncello':'Fresh lemon zest and oil, candied citrus and a sweet, bright finish.','St-Germain':'Fresh elderflower, pear, lychee and light floral sweetness.','Chambord':'Raspberry and blackcurrant, vanilla and gentle spice over a sweet berry body.','Maraschino liqueur':'Dry cherry, almond-like stone, floral notes and a lightly bitter finish.','Cherry Heering':'Deep ripe cherry, almond kernel and warm spice; round and fruit-rich.','Crème de cassis':'Blackcurrant, dark berry, high sweetness and a tart-skin finish.','Blue curaçao':'Orange peel and sweet citrus; color is vivid, flavor is orange-led.','Triple sec':'Orange peel, citrus oil and sugar; dryness and intensity vary by producer.','Falernum':'Lime, ginger, clove and almond-like spice; sweet, bright and tiki-friendly.','Pimento dram':'Allspice, clove, cinnamon and rum-like warmth; concentrated baking spice.','Ancho Reyes':'Dried chile, cocoa, raisin and warm pepper; sweet, earthy and gently hot.','Galliano':'Vanilla, anise, herbs and citrus with a sweet, aromatic finish.','Licor 43':'Vanilla, citrus and baking spice; smooth, sweet and warmly aromatic.','Strega':'Saffron-like spice, mint and aromatic herbs with honeyed sweetness.','Suze':'Gentian-root bitterness, earthy herbs and citrus; firm, dry and appetite-stimulating.','Cynar':'Herbal, earthy and bittersweet with vegetal notes and a rounded finish.','Averna':'Cola-like spice, citrus, roots and caramel; mellow, bittersweet and full.','Amaro Montenegro':'Orange, flowers, herbs and a softer bittersweet finish.','Amaro Nonino':'Orange peel, alpine herbs and spice with a polished, gently bitter finish.','Ramazzotti':'Dark herbs, citrus, licorice and caramel-like sweetness.','Lillet Blanc (aperitif wine)':'Light citrus, floral herbs and gentle quinine-like bitterness; wine-based and aperitif-like.','Pimm\'s No. 1':'Gin-based fruit, spice and herbal notes; sweet, light and designed for long drinks.','Advocaat':'Rich egg custard, vanilla and gentle spirit warmth; thick and dessert-like.','Irish cream':'Cream, cocoa, coffee and whiskey warmth; sweet and velvety.','Ouzo':'Anise and fennel, cooling and aromatic; turns cloudy when diluted with water.','Sambuca':'Sweet anise and licorice with a clean, cooling finish.','Absinthe':'Strong anise, fennel and wormwood-like herbs; botanical and high intensity, not a sugar liqueur.','Midori':'Sweet melon-candy aroma, honeydew and a light citrus finish.','Crème de violette':'Perfumed violet petals, soft berry and gentle sweetness; use sparingly.','Crème de menthe, green':'Cool mint, sweet herbal freshness and a long cooling finish.','Crème de menthe, white':'Cool mint and sugar without green coloring; fresh and sweet.','Coffee liqueur':'Roast coffee, cocoa and caramel; sweetness and bitterness vary by brand.','Crème de cacao':'Cocoa, vanilla and soft chocolate; white and dark styles differ in color and intensity.','Bärenjäger':'Honey, floral notes and soft grain-spirit warmth; rich and sweet.','Benedictine DOM':'Honeyed herbs, baking spice and citrus peel; rich but complex.','Bénédictine DOM':'Honeyed herbs, baking spice and citrus peel; rich but complex.','Green walnut nocino':'Green walnut husk, clove, cinnamon and bitter tannin; dark, earthy and spiced.','Limoncello':'Lemon zest oil, candied citrus and a sweet, bright finish.'};
function tasteLiqueur(n){if(namedLiqueurProfiles[n])return namedLiqueurProfiles[n];let s=n.toLowerCase(),parts=[];if(/cassis|blackcurrant/.test(s))parts=['blackcurrant','dark berry','tart skin'];else if(/raspberry|framboise|framboise/.test(s))parts=['ripe raspberry','red berry','bright fruit'];else if(/mûre|mure|blackberry/.test(s))parts=['blackberry','dark fruit','soft tannin'];else if(/peach|pêche|peche/.test(s))parts=['ripe peach','stone fruit','perfumed sweetness'];else if(/apricot/.test(s))parts=['apricot','stone-fruit kernel','soft citrus'];else if(/pear|poire|williams/.test(s))parts=['pear','orchard fruit','floral aroma'];else if(/apple|pomme|calvados/.test(s))parts=['apple','orchard fruit','warm spice'];else if(/elderflower|fiorente/.test(s))parts=['elderflower','pear','light floral notes'];else if(/orange|curaçao|curacao|triple sec|mandarin|cointreau/.test(s))parts=['orange peel','citrus oil','sweet-bitter finish'];else if(/coffee|café|kahl|tia maria/.test(s))parts=['roasted coffee','cocoa','caramel'];else if(/cacao|cocoa|chocolate|dorda/.test(s))parts=['cocoa','vanilla','dark chocolate'];else if(/hazelnut|nocello|frangelico|walnut|nocino|pistachio|almond|amaretto/.test(s))parts=['toasted nut','vanilla','gentle bitter kernel'];else if(/melon|midori/.test(s))parts=['melon','candy-like fruit','light citrus'];else if(/mint|menthe/.test(s))parts=['cool mint','sweet herb','fresh finish'];else if(/anise|ouzo|sambuca|pastis|pernod|raki/.test(s))parts=['anise','fennel','cooling herbs'];else if(/ginger/.test(s))parts=['fresh ginger','warm spice','citrus lift'];else if(/cinnamon|cannelle/.test(s))parts=['baking spice','cinnamon','warm sweetness'];else if(/honey|jäger|jager|drambuie|bé(n|)édictine|chartreuse|strega|genepy|génépy/.test(s))parts=['aromatic herbs','honeyed spice','long bittersweet finish'];else if(/amaro|fernet|bitter|aperol|campari|cynar|suze/.test(s))parts=['bitter roots','citrus peel','aromatic herbs'];else if(/cream|advocaat|baileys/.test(s))parts=['cream','vanilla','dessert spice'];else if(/berry|cassis|cherry|cerise|guava|pomegranate/.test(s))parts=['ripe fruit','bright berry','sweet-tart finish'];else parts=['botanical aroma','measured sweetness','a lingering finish'];return `${parts.map(x=>x[0].toUpperCase()+x.slice(1)).join(', ')}; sweetness, strength and finish vary by producer.`}
function productionLiqueur(n){let s=n.toLowerCase();if(/lillet|byrrh|port|rivesaltes/.test(s))return 'Wine-based aperitif or fortified wine, aromatized/blended according to regional practice; this is a related modifier, not always legally a liqueur.';if(/cream|advocaat/.test(s))return 'Typically a spirit base blended with dairy cream or egg-yolk custard and sweetener. Refrigeration, allergens and shelf-life depend on the label.';if(/amaro|fernet|aperol|campari|cynar|suze|bitter/.test(s))return 'Commonly produced by macerating and/or distilling roots, herbs, bark, spices and citrus in alcohol, then sweetening and blending. Exact recipes are often proprietary.';if(/coffee|café|kahl|tia maria|cacao|cocoa|chocolate/.test(s))return 'Coffee beans or cacao are extracted by infusion/maceration, sometimes with distillation, then blended with alcohol and sweetener. Producer methods vary.';if(/anise|ouzo|sambuca|pastis|pernod|raki|absinthe/.test(s))return 'Anise, fennel and other botanicals are macerated and/or distilled with alcohol; sugar and dilution behavior vary by style and local rules.';if(/nut|nocino|amaretto|frangelico|hazelnut|pistachio|almond/.test(s))return 'Nut, kernel or green-walnut flavors are commonly extracted by maceration/infusion, sometimes distillation, then sweetened. Check allergen statements on the bottle.';if(/crème|creme/.test(s))return 'Usually a fruit, flower or botanical infusion or distillate sweetened to a high sugar level. “Crème” describes richness/sugar, not dairy cream.';if(/fruit|berry|cassis|raspberry|mûre|mure|peach|pêche|pomegranate|cherry|limoncello|elderflower|melon|apple|pear|orange|curaçao|triple sec|yuzu|guava|strawberry/.test(s))return 'Often made by macerating or infusing fruit, peel or blossoms in a spirit, then sweetening and blending; some styles use distillation. Exact process varies by maker.';return 'Usually a flavored alcohol base made by botanical/fruit extraction, distillation or both, then sweetened and blended. Brand-specific methods may be proprietary; check the producer label.'}
const liqueurAliases={'D.O.M. Bénédictine':'Benedictine DOM','Blackcurrant liqueur (crème de cassis)':'Crème de cassis','Cassis liqueur':'Crème de cassis','Amaro Montenegro Rosso':'Amaro Montenegro','Bols blue':'Blue curaçao','Bols peach':'Peach liqueur','Bols triple sec':'Triple sec','Italian limoncello':'Limoncello'};
const liqueurExamples={'Amaretto':'Disaronno; Lazzaroni Amaretto','Amaro Averna':'Averna','Amaro Montenegro':'Amaro Montenegro','Amaro Nonino':'Nonino Quintessentia','Aperol':'Aperol','Benedictine DOM':'Bénédictine D.O.M.','Blue curaçao':'Bols Blue; Senior Curaçao of Curaçao','Crème de cassis':'Lejay; Giffard Crème de Cassis','Curaçao, dry':'Pierre Ferrand Dry Curaçao; Combier L’Original','Triple sec':'Cointreau; Combier; Giffard Triple Sec','Cointreau':'Cointreau','Grand Marnier':'Grand Marnier Cordon Rouge','Chartreuse, green':'Chartreuse Green','Chartreuse, yellow':'Chartreuse Yellow','Fernet-Branca':'Fernet-Branca','Frangelico':'Frangelico','Kahlúa':'Kahlúa','Tia Maria':'Tia Maria','Limoncello':'Pallini; Villa Massa','Maraschino liqueur':'Luxardo Maraschino; Maraska','St-Germain':'St-Germain','Midori':'Midori','Suze':'Suze','Cynar':'Cynar','Falernum':'John D. Taylor’s Velvet Falernum; BG Reynolds Falernum','Absinthe':'Pernod Absinthe; St. George Absinthe Verte','Advocaat':'Warninks; Bols Advocaat','Anisette':'Marie Brizard Anisette; Anis del Mono','Apple liqueur':'Berentzen Apfelkorn; Giffard Pomme','Apricot brandy':'Rothman & Winter Orchard Apricot; Giffard Abricot du Roussillon','Blackberry liqueur':'Giffard Crème de Mûre; Bols Crème de Mûre','Black walnut liqueur':'Nocino-style examples: Toschi Nocello; F.lli Francoli Nocino','Cacao liqueur, dark':'Tempus Fugit Crème de Cacao; Marie Brizard Cacao','Cacao liqueur, white':'Tempus Fugit Crème de Cacao Blanc; Marie Brizard White Cacao','Café liqueur':'Mr Black; Kahlúa; Tia Maria','Caraway liqueur':'Helbing Kümmel; Gilka Kaiser-Kümmel','Cherry liqueur, maraschino':'Luxardo Maraschino; Maraska Maraschino','Coconut liqueur':'Malibu; Kōloa Coconut Rum (category/product styles differ)','Crème de banane':'Giffard Banane du Brésil; Tempus Fugit Crème de Banane','Crème de framboise':'Giffard Crème de Framboise; Merlet Crème de Framboise','Crème de pêche':'Giffard Crème de Pêche; Briottet Crème de Pêche','Crème de violette':'Rothman & Winter Crème de Violette; Giffard Violette','Elderflower liqueur':'St-Germain; Giffard Fleur de Sureau','Ginger liqueur':'Domaine de Canton; Giffard Ginger of the Indies','Goldschläger':'Goldschläger cinnamon schnapps','Guavaberry liqueur':'St. Maarten Guavaberry liqueur','Hpnotiq':'Hpnotiq','Irish cream':'Baileys; Kerrygold Irish Cream','Kümmel':'Helbing; Gilka','Mandarin liqueur':'Mandarine Napoléon; Giffard Mandarine','Melon liqueur':'Midori; Bols Melon','Ouzo':'Ouzo 12; Plomari','Pama pomegranate liqueur':'Pama','Pastis':'Ricard; Pastis 51','Peach schnapps':'DeKuyper Peachtree; Archers Peach Schnapps','Pear liqueur':'Mathilde Poire; Giffard Poire Williams','Pineapple liqueur':'Giffard Caribena; Tempus Fugit Pineapple','Pistachio liqueur':'Bottega Pistacchio; Giffard Pistachio','Pomegranate liqueur':'Pama; Giffard Pomegranate','Raspberry liqueur':'Chambord; Giffard Crème de Framboise','Rhubarb liqueur':'Giffard Rhubarb; Zucca Rabarbaro (amaro, not a sweet liqueur)','Sambuca':'Molinari; Romana Sambuca','Sloe gin':'Plymouth Sloe Gin; Sipsmith Sloe Gin','Strawberry liqueur':'Giffard Fraise des Bois; Bols Strawberry','Vanilla liqueur':'Galliano Vanilla; Bols Vanilla','Violet liqueur':'Rothman & Winter; Giffard Violette','Walnut liqueur':'Toschi Nocello; Fratelli Brunello Nocino','Watermelon liqueur':'Midori (melon style); DeKuyper Watermelon Pucker','Yuzu liqueur':'Yuzushu producers such as Choya; Giffard Yuzu du Japon'};
const canonicalLiqueurNames=[...new Set(liqueurNames.map(n=>liqueurAliases[n]||n))];
const liqueurs=canonicalLiqueurNames.map((name,i)=>({name,category:liqueurCategory(name),taste:tasteLiqueur(name),examples:liqueurExamples[name]||'',use:['Add 5–15 ml to a sour, spritz or stirred drink; taste and adjust.','Pair with the matching fruit, citrus peel, coffee or spice in a cocktail.','Try a small 1:2 tasting pour with soda to learn its sweetness and aroma.'][i%3]}));
const spiritLessons=[
{key:'vodka',name:'Vodka',tag:'Neutral canvas',summary:'A spirit distilled from fermentable agricultural material and commonly rectified/filtered for a clean profile. “Neutral” is a style goal, not absence of all texture. Raw material, water, fermentation and filtration can still influence mouthfeel.',origin:'Vodka traditions developed across Eastern Europe; Russia and Poland have long, distinct histories. Exact national “first” claims are contested.',production:'Ferment grain, potato, fruit or other permitted agricultural material → distill/rectify → reduce with water → optionally filter → rest and bottle. Regulation and labeling vary by market.',taste:'Clean, soft to peppery or creamy; texture and faint grain/mineral character vary. Serve chilled neat for evaluation, or let the supporting ingredients lead.',types:'Wheat, rye, potato, corn, grape and other base materials; unflavoured, infused and flavoured styles.',serve:'Martini, Moscow Mule, Bloody Mary, highballs. Choose a texture that suits the drink rather than assuming all vodka is identical.'},
{key:'gin',name:'Gin',tag:'Juniper & botanicals',summary:'A juniper-led spirit whose identity is built from a botanical recipe: citrus, coriander, roots, seeds and flowers can shape the style.',origin:'Genever developed in the Low Countries; gin’s modern form grew in Britain. Gin became central to 18th-century London drinking culture.',production:'Neutral or grain spirit is redistilled with botanicals, infused, or combined with botanical distillates. Juniper must be the defining botanical in gin styles; rules differ by jurisdiction.',taste:'Juniper pine, citrus zest, coriander, rooty earth, floral or spice notes. London Dry is often crisp and juniper-forward; contemporary styles may emphasize citrus or florals.',types:'London Dry, distilled gin, compound gin, Old Tom, Plymouth, genever, navy strength, contemporary botanical. “Dry” and “London” are not necessarily a place description.',serve:'Martini, Negroni, G&T, Tom Collins, Gimlet. Match botanical intensity to tonic, vermouth and garnish.'},
{key:'whiskey',name:'Whiskey / whisky',tag:'Grain, still & oak',summary:'A grain spirit whose profile comes from mash bill, malting, fermentation, still design, climate, cask and time. Spellings often signal tradition, not quality.',origin:'Whisky-making developed over centuries in Scotland and Ireland; grain distilling traditions spread widely. Documentary records show practice, not one single inventor.',production:'Mill grain → mash starch into fermentable sugars → ferment → distill in pot or column stills → mature where the category requires → blend or bottle. Oak extracts color, tannin and aroma.',taste:'Grain, cereal, fruit, spice, vanilla, caramel, oak, smoke or medicinal peat. Age, cask, climate and blending all matter; age alone is not a quality score.',types:'Scotch single malt (one distillery, malted barley, pot still); blended Scotch (malt and grain components); bourbon (US, ≥51% corn mash bill, new charred oak); rye (jurisdiction-defined; US ≥51% rye); Irish (many styles, often triple-distilled but not always); Canadian, Japanese, Tennessee.',serve:'Old Fashioned, Manhattan, Whiskey Sour, highballs, neat tastings. Compare proofs and cask profiles side-by-side.'},
{key:'rum',name:'Rum',tag:'Sugarcane, many worlds',summary:'A broad family distilled from sugarcane juice, syrup or molasses. Fermentation and still choices create an unusually wide range of styles.',origin:'Sugarcane was domesticated in South and Southeast Asia and spread through global trade. Rum’s history is inseparable from colonialism, slavery and plantation economies in the Caribbean and beyond.',production:'Prepare cane material → ferment (short/clean or long/ester-rich) → pot, column or hybrid distill → optionally mature, blend or filter. “Dark” is not a reliable age category.',taste:'Light and crisp to grassy, fruity, funky, molasses-rich, woody or smoky. Cane juice often gives fresh vegetal notes; long fermentation and pot distillation can bring esters.',types:'Unaged white, gold, aged, overproof, molasses-based, cane-juice agricole/clairin/cachaça (distinct rules), Spanish-, English- and French-influenced traditions.',serve:'Daiquiri, Mojito, Mai Tai, Ti’ Punch, rum Old Fashioned. Use aromatic rum where the recipe needs character; don’t replace all rums one-for-one.'},
{key:'brandy',name:'Brandy',tag:'Fruit, wine & place',summary:'A spirit distilled from fermented fruit, most often wine grapes. Fruit source, distillation, cask, blending and regional law create many styles.',origin:'Wine distillation arose from early distilling knowledge and trade in Europe. Cognac and Armagnac became famous French appellations, but brandy traditions are global.',production:'Ferment fruit or wine → distill (pot or column) → mature or bottle unaged → blend and adjust. Cognac is a protected French wine-brandy appellation; Armagnac has its own regional production rules.',taste:'Grape, orchard fruit, dried fruit, flowers, spice, nuts, vanilla and oak. Young eaux-de-vie can be clear and vivid; aged styles gain oxidative and cask notes.',types:'Cognac (VS/VSOP/XO age categories); Armagnac; Spanish Brandy de Jerez; Calvados (apple/pear); pisco; grappa (pomace); fruit eaux-de-vie; American and other grape brandies.',serve:'Sidecar, Brandy Alexander, Crusta, Sazerac variants; serve neat in a tulip glass to appreciate aroma.'},
{key:'tequila',name:'Tequila',tag:'Blue Weber agave',summary:'A geographically protected Mexican spirit made from blue Weber agave within legally designated areas. Production choices range from fresh vegetal to cooked-agave and oak-rich.',origin:'Tequila developed in western Mexico, particularly Jalisco, from agave-fermentation and distilling traditions. Indigenous agave use predates the modern spirit category.',production:'Harvest mature agave → cook hearts (oven/autoclave/diffuser methods differ) → extract and ferment sugars → distill → bottle or age. Tequila must comply with Mexican denomination rules.',taste:'Cooked agave, pepper, citrus, herbs, earth and sometimes vanilla/oak. Process choices and maturation shift profile substantially.',types:'Blanco/plata (unaged or short rested); joven/gold (blend or coloring rules); reposado (aged at least 2 months); añejo (at least 1 year); extra añejo (at least 3 years). 100% agave vs mixto labeling matters.',serve:'Margarita, Paloma, Ranch Water, neat tasting. Match blanco with bright citrus; barrel-aged expressions can stand up to stirred drinks.'},
{key:'mezcal',name:'Mezcal',tag:'Agave & regional craft',summary:'A protected Mexican category encompassing many agave species and regional methods. Not every mezcal is smoky, and not every agave spirit is mezcal.',origin:'Agave has deep Indigenous cultural importance in Mexico. Mezcal-making traditions span multiple states; regional knowledge and local law matter.',production:'Cook agave (often pits, but not universally) → crush (manual, tahona or mill) → ferment → distill (often pot stills; vessels vary) → rest or mature. Methods vary by community and regulation.',taste:'Cooked agave, herbs, fruit, mineral and sometimes smoke; species and fermentation produce huge variation. Taste the actual bottle rather than assume “smoky.”',types:'Espadín and many wild/cultivated agaves; joven, reposado, añejo; artisanal/ancestral are regulated production terms in Mexico.',serve:'Sip neat in small pours; Margarita riffs, Naked & Famous, mezcal Negroni. Pair expressive bottles with enough dilution and fresh acid.'},
{key:'cachaça',name:'Cachaça',tag:'Brazilian cane spirit',summary:'Brazilian spirit distilled from fermented fresh sugarcane juice. Its character can be grassy, fruity or gently wood-influenced.',origin:'A distinctly Brazilian category that arose in the colonial period; its history is connected to sugar plantations and enslaved labor.',production:'Fresh cane juice is fermented and distilled; styles range from unaged to wood-matured. Brazilian rules define cachaça; it is not simply interchangeable with rum.',taste:'Fresh cane, grassy herbs, fruit and sometimes spice or local-wood character. Unaged cachaça can be lively and vegetal.',types:'Branca/prata (unaged or rested); aged and wood-influenced styles (native woods can contribute distinctive aromas).',serve:'Caipirinha is the essential template. Keep lime oils, sugar and crushed ice in balance; also explore aged cachaça in stirred drinks.'},
{key:'pisco',name:'Pisco',tag:'Grape spirit, Peru & Chile',summary:'A grape brandy made in Peru and Chile under different national rules. The two traditions are distinct, with different permitted grapes and processes.',origin:'Pisco’s name is tied to a Peruvian port and regional trade; Chile and Peru each have protected pisco identities and long histories.',production:'Ferment grapes → distill according to the producer country’s rules → generally bottle without long wood aging in traditional styles. Permitted grapes and proof requirements differ by country.',taste:'Grape, floral, citrus, stone fruit and sometimes earthy notes; aromatic intensity varies by grape and production.',types:'Peruvian pisco: styles include Puro, Acholado, Mosto Verde; Chilean pisco has its own categories and aging conventions. Do not collapse these into one spec.',serve:'Pisco Sour, Chilcano, punch. Shake with fresh citrus where appropriate; use a neutral pisco in delicate recipes and aromatic styles for expressive serves.'},
{key:'aperitif',name:'Aperitifs & vermouth',tag:'Wine, herbs & bitterness',summary:'Aperitifs are a broad pre-meal category; vermouth is fortified and aromatized wine. Their freshness, sugar and oxidation sensitivity make storage important.',origin:'European herbal wine traditions are ancient; modern vermouth styles developed in Italy and France in the 18th–19th centuries.',production:'Base wine is fortified and infused with botanicals; sweetness and color vary. Bitter aperitivo liqueurs are made by macerating/distilling botanicals in spirit or wine, then sweetening and blending.',taste:'From crisp, floral and dry to rich, spiced and bittersweet. Bitterness, sugar, wine acidity and botanicals create structure.',types:'Dry/extra-dry, bianco/blanc, rosso/sweet vermouth; aperitivo bitters, amari, quinquina and gentian-based aperitifs.',serve:'Martini, Manhattan, Negroni, Americano, spritz. Refrigerate opened vermouth and use promptly; it is wine, not an immortal spirit.'}
];
const pairFood=['Lime & grapefruit','Lemon & orange','Cucumber & mint','Ginger & pineapple','Cranberry & berry','Tomato & celery','Apple & pear','Coconut & banana','Coffee & cacao','Honey & stone fruit','Olive & brine','Basil & soft herbs','Chili & mango','Pomegranate & citrus','Pineapple & toasted spice','Melon & jasmine','Grapes & figs','Yogurt & cultured dairy','Grilled corn & avocado','Smoked fish','Fried seafood','Roast chicken','Charred vegetables','Aged hard cheese','Dark chocolate','Cured meats','Sushi & sashimi','Tacos & salsa','Citrus desserts','Nuts & dried fruit'];
const pairWhy={vodka:'A clean profile gives delicate ingredients room; match texture and seasoning rather than overpowering the base.',gin:'Juniper and botanical aromas echo herbs, citrus peel and savory greens; use bitter or saline elements to add structure.',whiskey:'Oak, grain spice and sometimes smoke complement seared flavors, aged cheese, caramelized foods and baking spices.',rum:'Cane sweetness, fruit esters and molasses notes connect with tropical fruit, char, spice and rich sauces.',brandy:'Fruit-derived aromatics mirror orchard fruit, dried fruit and pastry; oak-aged examples complement savory roast and nuts.',tequila:'Cooked agave, pepper and citrus pair naturally with lime, herbs, chile, grilled corn and bright salsas.',mezcal:'Agave, mineral and sometimes smoke connect with char, chile and earthy vegetables; choose a lighter hand with smoky bottles.',cachaça:'Fresh cane and grassy notes echo lime, herbs, tropical fruit and the toasted edges of grilled foods.',pisco:'Aromatic grape and floral notes flatter citrus, seafood, fruit, herbs and delicate desserts.',aperitif:'Bitterness and wine acidity refresh the palate, cut richness, and echo herbs, olives, citrus and savory snacks.'};
function foodLogic(food){let f=food.toLowerCase();if(/lime|lemon|grapefruit|citrus/.test(f))return 'Its natural acidity and peel oils echo a citrus garnish while refreshing the palate; keep added sourness in balance.';if(/mint|basil|herb|cucumber|jasmine/.test(f))return 'Fresh green aromatics can bridge botanical notes in the drink; use a light garnish or herb accent rather than muddling aggressively.';if(/ginger|chili|chile|spice/.test(f))return 'Warm spice amplifies aromatic heat; contrast it with cooling dilution, citrus or a little sweetness.';if(/coffee|cacao|chocolate/.test(f))return 'Roasted bitterness and cacao-like notes echo aged spirits or coffee modifiers; a small sweet counterpoint prevents the pairing turning harsh.';if(/fried|cheese|yogurt|cured|smoked|roast|fish|seafood/.test(f))return 'Salt, fat or smoke calls for refreshing acidity, carbonation or a measured bitter edge; match the drink’s intensity to the dish.';if(/pineapple|banana|coconut|mango|melon|berry|fruit|apple|pear|stone/.test(f))return 'A shared fruit aroma creates an easy bridge; choose fresh acidity or a dry finish so the pairing does not become cloying.';if(/corn|avocado|vegetable|tomato|celery/.test(f))return 'Savory vegetal notes pair well with herbs, saline touches and crisp acidity; avoid overpowering delicate textures.';if(/nut|fig|grape|dried/.test(f))return 'Nutty or dried-fruit notes echo barrel spice and oxidative aromas; use a restrained pour and consider the dish’s sweetness.';return 'Start with the dish’s dominant texture and seasoning, then match intensity and test one echo, contrast or bridge.'}
const pairings=spiritLessons.flatMap(s=>pairFood.map((food,i)=>({spirit:s.name,food,why:`${pairWhy[s.key]} ${foodLogic(food)}`,tech:['Echo: repeat a flavor already present in the dish.','Contrast: use acidity, bitterness or bubbles to refresh richness.','Bridge: add a shared herb, spice or fruit note to connect glass and plate.'][i%3]})));
const wineTerms=[['Acidity','Fresh, mouth-watering sensation; often makes wine feel bright.'],['Astringency','Drying/puckering sensation from tannin binding with saliva proteins.'],['Appellation','Legally defined geographical origin; rules vary by country.'],['Aroma','Smell associated with grape variety and fermentation.'],['Body','Weight and texture on the palate, influenced by alcohol, extract and sugar.'],['Botrytis / noble rot','Beneficial fungus that can concentrate sugars and create honeyed aromas in suitable conditions.'],['Brut','A sparkling-wine sweetness category; exact limits depend on regulations.'],['Climate / vintage','Seasonal conditions shape ripeness, acidity and yield; vintage is harvest year.'],['Cuvée','A batch, blend or selected wine; meaning varies by producer and region.'],['Lees','Spent yeast and particles; contact or stirring can add texture and bready notes.'],['Maceration','Contact of juice with grape skins/seeds to extract color, aroma and tannin.'],['Malolactic fermentation','Conversion of sharper malic acid to softer lactic acid; can add creamy notes.'],['Méthode traditionnelle','Second fermentation in bottle, with lees aging; associated with Champagne and other sparkling wines.'],['Minerality','A tasting descriptor (not literal soil flavor); use it carefully and concretely.'],['Must','Freshly crushed grape juice including skins, seeds and pulp.'],['Oak / élevage','Vessel and maturation choices affect oxygen exposure, texture and aromas.'],['Oxidation','Exposure to oxygen can change color and aroma; can be deliberate or a fault.'],['Residual sugar','Fermentable sugar remaining after fermentation; influences sweetness and body.'],['Rosé','Pink wine made by limited skin contact, blending where legal, or other methods.'],['Tannin','Phenolic structure, especially from skins, seeds and oak; can feel drying.'],['Terroir','Interacting place factors: climate, soil, topography, biodiversity and human choices.'],['Vintage / non-vintage','Single harvest vs blend across harvest years.'],['Volatile acidity','Acetic-acid-related aromas; low levels can add lift, excessive levels are a fault.'],['Whole-cluster','Fermentation with some or all grape stems; may add spice, structure and herbal character.']];
wineTerms.push(['AVA','American Viticultural Area: a delimited U.S. grape-growing origin, not a quality grade.'],['Blanc de blancs','Sparkling wine made from white grapes, often Chardonnay in Champagne.'],['Blanc de noirs','White sparkling wine made from dark-skinned grapes with limited color extraction.'],['Chaptalization','Adding sugar to must before/during fermentation where legally permitted to raise potential alcohol.'],['Decanting','Separating wine from sediment and/or aerating it; not required for every bottle.'],['Demi-sec','A sweetness term whose legal range depends on the region and wine style.'],['Dry','Low residual sugar by legal threshold; high fruit aroma can still taste sweet.'],['Extra brut','A very low-dosage sparkling style; exact limits are regulated.'],['Fining','Clarifying wine with an agent that binds suspended material; allergens can matter.'],['Filtration','Removing particles or microbes through a filter; choices affect stability and texture.'],['Fortified wine','Wine strengthened with spirit, often changing alcohol, sweetness and maturation.'],['Lees aging','Maturation on dead yeast cells; can add texture, savory notes and autolytic aromas.'],['Maceration carbonique','Whole berries ferment with intracellular carbon dioxide; can yield vivid fruit and soft tannin.'],['Négociant','A wine merchant or company that may buy grapes, must or wine and produce/blend.'],['Pet-nat','Informal term for pétillant naturel, bottled before primary fermentation completes.'],['Phylloxera','A vine pest that devastated European vineyards; grafting onto resistant rootstocks helped recovery.'],['Pigeage','Punching down the cap of skins during red fermentation to manage extraction.'],['Remuage','Riddling bottles to move lees toward the neck in traditional-method sparkling wine.'],['Reserve','A label term with different meanings and levels of legal protection by country.'],['Skin contact','Time juice stays with grape skins; affects color, tannin and aroma.'],['TCA / cork taint','A musty, damp-cardboard fault associated with haloanisoles; not every cork problem is TCA.'],['Tirage','Addition of yeast/sugar for second fermentation in traditional-method sparkling wine.'],['Ullage','Headspace between wine and closure; can signal evaporation or storage conditions.'],['Veraison','Color change and softening as grapes begin ripening.'],['Vinification','The process of making wine from grapes or must.'],['WSET SAT','Structured tasting approach for appearance, nose, palate and conclusions.']);
const wineStyles=[['Still red','Red grapes ferment with skin contact; color and tannin vary from light Pinot to structured Cabernet.'],['Still white','Usually pressed before fermentation; styles span crisp aromatic to textured barrel-aged.'],['Rosé','Pink styles use brief skin contact or other permitted methods; dry through sweet.'],['Orange / skin-contact','White grapes fermented or macerated with skins; texture, tannin and color vary widely.'],['Sparkling','Carbonated through bottle, tank or other methods; dosage and lees aging shape profile.'],['Fortified','Wine fortified with spirit; Port, Sherry, Madeira and vermouth differ in sweetness and production.'],['Dessert / sweet','Sweetness can result from late harvest, noble rot, freezing, drying or arrested fermentation.'],['Low / no alcohol','Alcohol is reduced or fermentation managed; label law and flavor outcomes vary.']];
const wineGrapes=[['Chardonnay','Adaptable; apple/citrus to stone fruit, with oak/lees adding texture. Burgundy, Champagne, California, Australia.'],['Sauvignon Blanc','High-toned citrus, green herbs and gooseberry; Loire, Bordeaux, Marlborough.'],['Riesling','High acidity; lime, stone fruit and florals, dry through sweet; Mosel, Alsace, Clare Valley.'],['Pinot Noir','Red cherry, rose and earthy nuance; Burgundy, Oregon, Central Otago.'],['Cabernet Sauvignon','Blackcurrant, cedar and firm tannin; Bordeaux, Napa, Coonawarra.'],['Syrah / Shiraz','Dark fruit, pepper, savory notes; Rhône, Barossa, Washington.'],['Tempranillo','Red/dark fruit, leather and oak spice; Rioja, Ribera del Duero.'],['Sangiovese','Sour cherry, herbs and lively acidity; Tuscany.'],['Chenin Blanc','Apple, quince, honey, high acid; Loire, South Africa.'],['Grenache / Garnacha','Red fruit, spice and warmth; Rhône, Spain, Australia.'],['Nebbiolo','Rose, tar-like aroma, high acid and tannin; Barolo, Barbaresco.'],['Pinot Grigio / Gris','Citrus and pear through richer textured styles; Italy, Alsace, Oregon.']];
const beerStyles=[['Pilsner','Pale lager; crisp, floral or spicy hops, clean malt; pair with fried fish or dumplings.'],['Helles','Soft malt-forward pale lager, gentle bitterness; roast chicken, pretzels.'],['Dunkel','Dark lager with bread crust, toast and caramel; sausages, roast pork.'],['Vienna lager','Amber lager with toasted malt and restrained bitterness; tacos, grilled vegetables.'],['Hefeweizen','Wheat ale with banana/clove yeast character and soft body; salads, spicy dishes.'],['Belgian witbier','Wheat, citrus peel and coriander; seafood, herbs, light curries.'],['Pale ale','Balanced malt and hops; burgers, fried snacks.'],['IPA','Hop-forward; citrus, pine, tropical or bitter. Match intensity with chile, fried food or assertive cheese.'],['West Coast IPA','Dry, clear, pronounced bitterness and resin/citrus; grilled meats.'],['Hazy IPA','Soft texture and juicy hop aroma; spicy food, salty snacks.'],['Porter','Brown malt, cocoa and toast; barbecue, mushrooms.'],['Stout','Roast coffee/cocoa, creamy to dry; oysters, chocolate.'],['Saison','Dry, peppery, fruity farmhouse ale; charcuterie, roast vegetables.'],['Lambic / gueuze','Spontaneous/wild fermentation, tart and complex; rich cheese, fruit desserts.'],['Sour ale','Acidity and fruit/microbe character vary; rich or fatty food can balance tartness.'],['Barleywine','Strong, malty, dried-fruit richness; blue cheese, caramel desserts.'],['Kölsch','Light, delicate ale-lager hybrid; seafood, salads.'],['Bock / Doppelbock','Malt-rich lager, caramel to dark fruit; roast meats, aged cheese.'],['Amber ale','Caramel malt with moderate hop; grilled sausages, pizza.'],['Brown ale','Nutty, cocoa and caramel notes; mushrooms, roast poultry.']];
function esc(s){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function go(page){currentPage=page;location.hash=page;render()}
function setRoute(){let p=location.hash.replace('#','')||'home';const allowed=['home','cocktails','shots','spirits','liqueurs','wine-beer','pairings','craft','service','tools','games','assistant'];currentPage=allowed.includes(p)?p:'home';render()}
window.addEventListener('hashchange',setRoute);$('#main-nav').addEventListener('click',e=>{const a=e.target.closest('[data-page]');if(a){e.preventDefault();go(a.dataset.page);$('#sidebar').classList.remove('open')}});$('#mobile-menu').onclick=()=>$('#sidebar').classList.toggle('open');$('#search-open').onclick=()=>openGlobalSearch();$('#today-date').textContent=new Intl.DateTimeFormat('en',{weekday:'short',month:'short',day:'numeric'}).format(day);$('#export-data').onclick=exportData;
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(window._toast);window._toast=setTimeout(()=>t.classList.remove('show'),2400)}
function shellTitle(label){$('#crumb').innerHTML=`YOUR PERSONAL BAR / <b>${label.toUpperCase()}</b>`;$$('.nav-link').forEach(a=>a.classList.toggle('active',a.dataset.page===currentPage))}
const routeDeepDives={
home:{title:'Build a study habit that transfers to service',why:'Reading becomes skill when you retrieve, perform, observe and reflect. Use this loop for any topic in the guide.',steps:['Choose one observable skill and define what “good” looks like before practice.','Study one short section, then close it and explain the idea in your own words.','Perform a safe, measured practice rep; compare to a known standard or venue SOP.','Ask for specific feedback from a trusted lead; record one thing to retain and one to change.','Return after a delay and repeat the rep in a different context.'],debug:'If a concept will not stick, make it smaller: name the cue, action and check. Do not use XP or streaks as a measure of professional competence.',quality:'Distinguish a study estimate from an approved recipe, legal rule or audited business figure.'},
cocktails:{title:'Recipe execution: spec → setup → taste → repeat',why:'A written formula is only one part of a drink. Ingredient condition, measure, dilution, temperature, glass and service timing change the result.',steps:['Read the full spec and identify method, ice, glass, garnish, allergen and any unusual ingredient before starting.','Measure in the venue’s approved unit; prepare the glass and fresh ice before mixing.','Use the stated method: shake for rapid chilling/aeration, stir for clarity/controlled dilution, build to protect bubbles.','Taste a small sample at service temperature; identify one sensation (sharp, sweet, hot, thin, bitter or muted).','Change one variable, document the exact change, then cost and repeat the approved final spec.'],debug:'A weak drink is not automatically fixed by adding sugar. Check measure, temperature, dilution, citrus freshness, syrup concentration and ice first.',quality:'The library offers study specs. Venue specifications, product labels, allergen controls and responsible-service rules take precedence.'},
shots:{title:'Short serves: control, consent and alternatives',why:'Small-volume drinks may still contain a meaningful amount of alcohol, and rapid consumption increases risk. A shot is not a measure of impairment.',steps:['Treat each short serve as an optional, measured menu item; describe ingredients and approximate strength honestly.','Offer a slower format, water and a thoughtful alcohol-free alternative without stigma.','Check age/ID and service obligations under local law; follow the venue’s refusal-of-service policy.','Confirm allergens from the actual manufacturer label and recipe; avoid unsupported “safe” assurances.','If a guest shows signs of risk, stop alcohol service as required, involve a manager and prioritize safety.'],debug:'Do not use drinking games, speed challenges, flame stunts or pressure. Do not assume coffee, food, water or a shower makes a person sober.',quality:'The listed mini specs are educational and vary by venue. Verify local pour-size, menu, labeling and service rules.'},
spirits:{title:'Taste a spirit by following its production chain',why:'Raw material is a clue, not destiny. Fermentation, distillation, maturation, blending, dilution and the actual producer shape the glass.',steps:['Read the label for category, origin, strength, age statement and producer claims; note what the label does not tell you.','Smell first without swirling, then gently aerate; record three concrete aromas rather than only “smooth.”','Taste a small measured sample at a safe, controlled strength; note sweetness, acidity, texture, alcohol warmth and finish.','Compare two examples side by side while changing one variable (region, still, maturation or proof).','Connect the sensory difference to production evidence, but mark a hypothesis as a hypothesis.'],debug:'“Smooth,” “premium,” “natural” and “single” are not complete technical descriptions. Category laws differ; consult the relevant authority for current definitions.',quality:'Tasting descriptions are typical tendencies, not guarantees. Brand examples are illustrative, not endorsements.'},
liqueurs:{title:'Use modifiers by function, not by bottle color',why:'A liqueur contributes several things at once—sweetness, aroma, alcohol, color, texture and sometimes allergens. Substitution changes the whole formula.',steps:['Read the exact product label and record its category, ABV, declared allergens and storage advice.','Taste a small sample, then describe aroma, sweetness, bitterness, texture and finish separately.','Assign a job in the drink: sweetener, bitter counterweight, botanical bridge, fruit aroma, texture or visual cue.','Substitute only one modifier at a time; reduce other sweetener if the replacement is sweeter, then retaste.','Cost by the actual measured dose and track brand/formula changes in the approved recipe.'],debug:'Names such as crème, cream, curaçao or amaro do not guarantee identical sugar, dairy status, flavor or legal classification across markets.',quality:'Producer formulations and allergen statements can change. Confirm the current label for every service batch.'},
'wine-beer':{title:'Taste fermented drinks with a repeatable grid',why:'A structured observation keeps grape/beer style, production claims and personal preference from being confused.',steps:['Record producer, style/region, vintage or batch, serving condition and storage history when available.','Observe appearance, then smell; note intensity and specific fruit, floral, spice, fermentation or maturation cues.','Taste for sweetness/dryness, acidity, bitterness, alcohol warmth, tannin (wine), carbonation, body and finish.','Name one production choice that might explain a cue; avoid claiming a soil or region caused a flavor without evidence.','Try the same beverage with a small bite of food and describe what changed in the drink and dish.'],debug:'A style name or region suggests possibilities but cannot establish quality. Fault diagnosis and current appellation rules need trained, current sources.',quality:'Examples and serving suggestions are starting points. Follow label, venue, licensing and safe-storage guidance.'},
pairings:{title:'Run a small, fair pairing test',why:'Pairing is a sensory hypothesis, not a universal match. Salt, temperature, recipe, portion and personal preference can change the outcome.',steps:['Taste the dish alone and name its dominant intensity, fat, salt, acid, heat, aroma and texture.','Taste the drink alone at its intended temperature; note sweetness, bitterness, acid, alcohol warmth and bubbles.','Test one relationship: echo a shared aroma, contrast richness, or bridge through a compatible middle note.','Use small measured samples and change only one element; include a non-alcoholic option and allergy-safe process.','Write what improved, what clashed and for whom; refine the menu description to avoid promising a universal result.'],debug:'High alcohol can intensify chile heat; sweetness may soften perception but is not a medical remedy. Check actual allergens and cross-contact controls.',quality:'Pairing examples are ideas to test with your actual recipe, ingredients and guest context.'},
craft:{title:'Develop a drink with controlled iteration',why:'A signature becomes repeatable when its purpose, sensory target, recipe, prep and service controls are explicit.',steps:['Write a one-sentence brief: intended guest, occasion, flavor direction, strength impression, price and operational constraint.','Choose a drink family and assign ingredient roles before adding extra components.','Make three small measured samples; change a single variable (acid, sugar, modifier or dilution) between versions.','Taste blind if practical; record the winner, actual yield, ice, glass, garnish, allergens and exact batch method.','Cost, stress-test at service pace, train staff and set a review date for sales/guest feedback.'],debug:'Complexity is not the same as originality. A component that adds prep, waste or ticket time needs a clear sensory or guest value.',quality:'Any ABV estimate, pricing or shelf-life requires product-specific data and applicable venue rules; do not infer safety from taste.'},
service:{title:'A reliable guest interaction under pressure',why:'Good service pairs warmth with accurate listening, clear options, boundaries and safe escalation.',steps:['Welcome without assumptions; read the guest’s cues and allow room to decline conversation.','Ask one useful, open preference question; clarify base, flavor, sweetness, strength impression and budget only when relevant.','Offer two concise, truthful options and explain material differences, price and non-alcoholic alternatives.','Repeat the order and verify allergies using recipe/label evidence and the venue’s escalation procedure.','Check back at a natural time, respond without defensiveness, and document/hand off only what policy requires.'],debug:'Do not make unsupported medical, allergy-safe, “low alcohol” or sobriety claims. If unsure, pause service and involve the designated lead.',quality:'Follow local law and house SOP for age checks, refusal, harassment, emergencies, accessibility and privacy.'},
tools:{title:'Make the station safe before making it fast',why:'Tools, glass, ice, chemicals and prep are control points. A quick setup prevents avoidable contamination, breakage and service errors.',steps:['Inspect tools, glass and equipment; remove chipped glass and report unsafe or malfunctioning items.','Separate clean tools from used tools and chemicals; keep chemicals labeled and away from food/beverage contact surfaces.','Prepare garnishes and perishables using approved handwashing, sanitation, time/temperature and date-marking procedures.','Set a repeatable station map and par levels; keep ice protected and never scoop with glassware.','Close by cleaning, storing, counting critical stock and documenting equipment faults or discarded product.'],debug:'Do not guess sanitizer concentration, contact time or food shelf-life; use product instructions and current local food-code/venue procedures.',quality:'This is a learning checklist, not a substitute for food-handler training or the relevant authority’s requirements.'},
games:{title:'Turn quiz misses into a deliberate practice plan',why:'A score shows recall in one round. Professional skill also needs explanation, hands-on performance, judgment and feedback.',steps:['Answer before revealing feedback; state why the best answer fits and why a distractor is tempting.','Tag the miss: knowledge gap, unit conversion, rushed reading, unsafe assumption or unclear terminology.','Review the related lesson or source; rewrite the rule in your own words and create one example.','Repeat the skill after a delay, then apply it to a different drink, guest or operation scenario.','Track recurring errors as a practice priority—not as a measure of intelligence or job readiness.'],debug:'A multiple-choice correct answer does not certify competency, legal compliance, responsible service or food safety.',quality:'Use quizzes for low-stakes retrieval, and seek supervised practice for consequential real-world tasks.'},
assistant:{title:'Use the local mentor without oversharing',why:'A local rule-based guide can prompt study but cannot inspect current law, labels, venue SOPs or your guest’s condition.',steps:['Ask a bounded educational question without entering names, contact details, health information, credentials or confidential venue data.','Provide generic context such as drink family, flavor target and available tools—not personally identifying details.','Treat the answer as a starting point; check the relevant lesson, supplier label, official rule or venue manager.','For emergency, legal, medical, allergen or intoxication decisions, stop and use the qualified local procedure.','Keep browser backups private; clear them from shared devices when no longer needed.'],debug:'This offline coach is not a human expert, live search or emergency service; its omissions and errors are possible.',quality:'No personal data is transmitted by the app, but local browser storage and exported files are not encrypted.'}
};
function deepeningMarkup(route){const d=routeDeepDives[route];if(!d)return'';return `<section class="route-deepening"><div class="eyebrow">FIELD PRACTICE · DEEPER EXECUTION</div><h2>${esc(d.title)}</h2><p class="deepening-why">${esc(d.why)}</p><div class="deepening-columns"><article><h3>Work through it</h3><ol>${d.steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol></article><article><h3>Common trap & professional check</h3><p>${esc(d.debug)}</p><div class="deepening-quality"><b>Quality / safety boundary</b><span>${esc(d.quality)}</span></div></article></div></section>`}
function render(){shellTitle(currentPage.replace('-',' & '));let root=$('#app-content');({home:homePage,cocktails:cocktailPage,shots:shotsPage,spirits:spiritsPage,liqueurs:liqueurPage,'wine-beer':wineBeerPage,pairings:pairingPage,craft:craftPage,service:servicePage,tools:toolsPage,games:gamesPage,assistant:assistantPage}[currentPage]||homePage)(root);root.insertAdjacentHTML('beforeend',deepeningMarkup(currentPage))}
function homePage(root){let foundationCount=10+serviceTopics.length;let progressDone=store.completed.filter(x=>spiritLessons.some(s=>s.key===x)||/^svc\d+$/.test(x)).length;let pct=Math.round((progressDone/foundationCount)*100);let todayTip=tips[(day.getDate()+store.tipsSeen)%tips.length];root.innerHTML=`<section class="hero"><div><div class="eyebrow">YOUR PERSONAL LEARNING BAR · ISSUE 01</div><h1>Good drinks begin<br>with good questions.</h1><p>A practical field guide for learning the classics, understanding what’s in the bottle, and making every guest feel welcome.</p></div><div class="hero-cta"><button class="btn btn-lime" onclick="go('cocktails')">Explore the classics →</button></div></section>
<div class="stats-grid"><div class="stat-card"><div><small>CLASSICS TO EXPLORE</small><strong>200</strong></div><span class="stat-icon">◉</span></div><div class="stat-card"><div><small>LIQUEURS IN THE CABINET</small><strong>${liqueurs.length}+</strong></div><span class="stat-icon">✳</span></div><div class="stat-card"><div><small>LEARNING STREAK</small><strong>${store.streak||1} <small style="display:inline;font:11px 'DM Sans'">days</small></strong></div><span class="stat-icon">⌁</span></div><div class="stat-card"><div><small>FAVORITES SAVED</small><strong>${store.favorites.length}</strong></div><span class="stat-icon">♡</span></div></div>
<div class="section-head"><div><h2>Today at your bar</h2><p>A small skill, practiced often, becomes instinct.</p></div><button class="link-btn" onclick="store.tipsSeen++;save();render()">↻ Another tip</button></div>
<div class="grid-2"><div class="daily-card"><div class="daily-icon">✧</div><div><div class="eyebrow">DAILY TIP · SERVICE & TECHNIQUE</div><div class="daily-tip">${esc(todayTip)}</div><div style="margin-top:12px"><button class="btn btn-small" onclick="go('games')">Put it into practice →</button></div></div></div><div class="card"><h3>Your learning path</h3><p>Mark lessons complete as you build your personal study routine.</p><div class="progress-wrap"><div class="progress-label"><span>Foundation modules</span><b>${store.completed.length}/10 marked complete</b></div><div class="progress"><span style="width:${pct}%"></span></div></div><div class="pill-row" style="margin-top:14px"><span class="tag">${store.quizBest?`Best quiz: ${store.quizBest}/10`:'Try a knowledge game'}</span><span class="tag gold">Saved on this device</span></div></div></div>
<div class="section-head"><div><h2>Choose your next pour</h2><p>Start anywhere. Go deep whenever curiosity strikes.</p></div></div><div class="grid-3">${[['cocktails','◉','Cocktail library','200 recipes in oz + ml, with technique, flavor and history.'],['spirits','◌','Spirits atlas','How spirits are made, what shapes flavor, and how to serve.'],['wine-beer','⌁','Wine & beer','Production, styles, regions, tasting and pairing essentials.'],['liqueurs','✳','Liqueur cabinet',`${liqueurs.length}+ liqueur styles and their flavor roles.`],['craft','✧','Build a signature','A repeatable framework for balance, iteration and cost.'],['service','⌂','Hospitality & operations','Practical service, stock, safety and business foundations.']].map(x=>`<article class="card module-card" onclick="go('${x[0]}')"><span class="arrow">↗</span><div class="module-icon">${x[1]}</div><h3>${x[2]}</h3><p>${x[3]}</p></article>`).join('')}</div>
<div class="section-head"><div><h2>Quick tools</h2><p>Useful at the bar and during study.</p></div></div><div class="grid-3"><article class="card module-card" onclick="go('craft')"><div class="module-icon">＄</div><h3>Drink cost calculator</h3><p>Ingredient cost, menu price and pour-cost percentage.</p></article><article class="card module-card" onclick="go('games')"><div class="module-icon">▦</div><h3>Knowledge games</h3><p>Practice with quick quizzes and flavor-family drills.</p></article><article class="card module-card" onclick="go('assistant')"><div class="module-icon">✦</div><h3>Ask your bar mentor</h3><p>Private local mentor using the guide stored in this page.</p></article></div>`}
function cocktailPage(root){let filtered=cocktails.slice(0,200).filter(c=>(cocktailFilter==='All'||c.family===cocktailFilter||c.spirit===cocktailFilter.toLowerCase())&&(`${c.name} ${c.base} ${c.family} ${c.taste}`.toLowerCase().includes(cocktailQuery.toLowerCase())));root.innerHTML=`<div class="content-intro"><div class="title-row"><div><div class="eyebrow">THE RECIPE LIBRARY · 200 MUST-KNOW CLASSICS</div><h1 class="display">Cocktails, from first principles.</h1><p class="lead">Explore essential recipes, flavor profiles, technique and carefully qualified origin notes. Specs are practical starting points—measure, taste and adapt responsibly.</p></div><div class="search-box"><span>⌕</span><input id="cocktail-search" aria-label="Search cocktails by drink, spirit, style or flavor" placeholder="Search drinks, spirit, style…" value="${esc(cocktailQuery)}"></div></div></div><div class="filter-row">${['All','sour','spirit-forward','highball','bitter aperitivo','tropical','sparkling','fizz','gin','whiskey','rum','tequila','vodka'].map(f=>`<button class="filter-chip ${cocktailFilter===f?'active':''}" data-filter="${f}">${f==='All'?'All recipes':f[0].toUpperCase()+f.slice(1)}</button>`).join('')}</div><div class="pill-row" style="margin-bottom:12px"><span class="tag">${filtered.length} drinks</span><span class="tag gold">oz ⇄ ml on every recipe</span><span class="tag red">Origin stories: folklore flagged</span></div><div class="cocktail-grid">${filtered.map(c=>`<article class="cocktail-card" onclick="showCocktail(${c.rank-1})"><div class="card-top"><span class="tag">${esc(c.family)}</span><button class="fav ${store.favorites.includes(c.name)?'on':''}" onclick="event.stopPropagation();toggleFav(&quot;${esc(c.name)}&quot;)">${store.favorites.includes(c.name)?'♥':'♡'}</button></div><h3>${esc(c.name)}</h3><div class="sub">${esc(c.base)} · ${esc(c.glass)}</div><div class="recipe-preview">${esc(c.spec)}</div><div class="card-footer"><span>${esc(c.taste.split('.')[0])}</span><span>OPEN →</span></div></article>`).join('')||'<div class="empty-state"><strong>No drinks found</strong>Try another name, spirit or style.</div>'}</div><div class="section-head"><div><h2>Cocktail families</h2><p>Structure is a faster way to understand and invent drinks than memorizing names alone.</p></div></div><div class="grid-3">${[['Sours','Base spirit + citrus + sweetener. Shake, taste and tune the sweet/acid balance. Examples: Daiquiri, Whiskey Sour, Sidecar.'],['Spirit-forward','Base spirit + vermouth/liqueur + bitters. Stir cold with controlled dilution. Examples: Martini, Manhattan, Old Fashioned.'],['Highballs & Collins','Spirit lengthened with soda, tonic or ginger beer. Build over fresh ice; protect carbonation. Examples: Gin Rickey, Tom Collins, Mule.'],['Fizzes & sparkling','Citrus, spirit or liqueur and often sugar, topped or shaken with bubbles. Examples: Gin Fizz, French 75.'],['Aperitivo / bittersweet','Bitter liqueur or amaro balanced by vermouth, spirit, soda or citrus. Examples: Americano, Negroni.'],['Punch & tropical','Often combines spirit, citrus, sweetener, spice and fruit; balance and dilution are essential. Examples: Planter’s Punch, Mai Tai.']].map(x=>`<article class="card"><h3>${x[0]}</h3><p>${x[1]}</p></article>`).join('')}</div>`;$('#cocktail-search').oninput=e=>{cocktailQuery=e.target.value;cocktailPage(root);const inp=$('#cocktail-search');inp.focus();inp.setSelectionRange(inp.value.length,inp.value.length)};$$('[data-filter]').forEach(b=>b.onclick=()=>{cocktailFilter=b.dataset.filter;cocktailPage(root)})}
function toggleFav(name){if(!cocktails.some(c=>c.name===name))return;let i=store.favorites.indexOf(name);i<0?store.favorites.push(name):store.favorites.splice(i,1);if(save())toast(i<0?'Saved to your favorites':'Removed from favorites');render()}
function ingredientRole(c,item,index){const x=item.toLowerCase();if(/lemon|lime|grapefruit|citrus|vinegar/.test(x))return'Acid / citrus: sets brightness and balance. Taste the actual product; acidity varies.';if(/syrup|sugar|honey|orgeat|grenadine|cordial|nectar/.test(x))return'Sweetener / body: rounds, adds texture or aroma. Check concentration and subtract sweetness elsewhere before changing a spec.';if(/soda|tonic|ginger beer|sparkling|champagne|prosecco|carbonated/.test(x))return'Length / carbonation: changes volume, texture and dilution. Add and handle as the recipe specifies to protect bubbles.';if(/bitters|saline|salt|pepper|hot sauce|season/.test(x))return'Seasoning: a small amount can shift aroma, bitterness or savoriness. Measure and add only to the approved spec.';if(/egg|cream|milk|yogurt|aquafaba/.test(x))return'Texture ingredient: affects body/foam and may introduce allergens or special handling requirements; verify exact product and SOP.';if(/water|ice/.test(x))return'Dilution / temperature: part of the formula. Ice condition, contact time and service temperature change the result.';if(/peel|twist|garnish|mint|cherry|olive|sprig|wedge/.test(x))return'Aroma / garnish cue: contributes a first impression or flavor signal. Prep safely and use only when the house spec calls for it.';if(/vermouth|liqueur|amaro|aperitivo|cura[cç]ao|triple sec|chartreuse|sherry|port/.test(x))return'Modifier: adds aroma, sweetness, bitterness, wine character or texture. Check product sweetness, ABV, freshness and allergens.';if(c.base&&x.includes(String(c.base).toLowerCase()))return'Base spirit: carries the main alcoholic and aromatic character. Keep the measured house pour and responsible portion.';if(index===0)return'Lead component in this listed spec: confirm whether it is the base or primary flavor source from the source/house card.';return'Supporting component: identify its sensory job by tasting or checking the approved recipe note; do not infer from its name alone.'}
const cocktailFamilyLabs={
'sour':{purpose:'Acid provides lift, sweetener rounds it, base carries aroma; balance must be judged at the actual serve temperature.',steps:['Taste the citrus and syrup separately; their intensity and sugar concentration vary.','Shake with consistent ice until cold and diluted; strain as specified.','Taste a small sample. If sharply sour, verify measured syrup and citrus before adjusting.','If flat or cloying, check freshness, dilution, temperature and aroma before changing the base.'],trap:'There is no universal sour ratio: citrus acidity, syrup concentration, spirit proof and guest preference vary.'},
'spirit-forward':{purpose:'A spirit-led build depends on measured modifier, controlled chilling/dilution and aromatic garnish.',steps:['Chill the serving glass and use fresh, hard ice in the mixing vessel.','Measure spirit, vermouth/modifier and bitters; check vermouth freshness and storage.','Stir and taste cold; seek integration rather than relying on a fixed stir time.','Express garnish over the surface, then smell and taste again.'],trap:'“Dry” is ambiguous. Confirm the guest’s preference and follow the exact house spec.'},
'highball':{purpose:'A highball is a temperature, ice, glass and carbonation system as much as a spirit-and-mixer ratio.',steps:['Use a clean chilled glass and fresh, dense ice to reduce rapid melt.','Measure base and mixer; keep carbonated ingredients cold and sealed until use.','Add bubbles last and lift gently once only if needed to combine.','Serve promptly; note whether the first and last sips remain balanced.'],trap:'Over-stirring, warm mixer, small wet ice or a warm glass quickly flattens the drink.'},
'fizz':{purpose:'Fizzes combine a chilled base with controlled aeration and often a delicate carbonated finish.',steps:['Separate any shake step from the sparkling top-up; never shake sealed carbonated liquid.','Use a clean, cold glass and chilled bubbles; pour gently to manage foam.','Check the spec’s egg/dairy/allergen handling if applicable.','Serve immediately and assess aroma, texture and final sweetness.'],trap:'Foam changes volume; use the approved measured house spec.'},
'sparkling':{purpose:'Bubbles carry aroma and lift, but carbonation is easily lost through temperature, handling and excess agitation.',steps:['Chill the sparkling component and glass; open and pour with control.','Prepare and chill the non-carbonated base first.','Top gently at service; use the exact house glass and measure.','Deliver promptly and check whether sweetness and strength feel guest-appropriate.'],trap:'Do not assume every sparkling wine is interchangeable; follow the recipe and product character.'},
'tropical':{purpose:'Tropical and punch-style recipes balance intense ingredients; dilution and batch consistency are central.',steps:['Measure every juice, syrup, spice and spirit; record product and fresh/prepared status.','Taste components individually so sweetness, acidity and bitterness are understood.','Shake or blend as directed, using repeatable ice and method.','Taste after dilution; garnish only when it adds aroma or a clear cue.'],trap:'More fruit does not automatically make a drink balanced; do not mask alcohol with sweetness.'},
'bitter aperitivo':{purpose:'Bitter, sweet, wine and spirit components interact; temperature and dilution soften or expose bitterness.',steps:['Measure every component and check fortified-wine freshness/storage.','Stir or build as specified; use a consistent ice size.','Taste cold, checking bitterness, sweetness and alcohol warmth separately.','Change only within the approved recipe and document the adjustment.'],trap:'Bitterness preference varies widely; describe it honestly and offer a gentler alternative.'},
'modern classic':{purpose:'Named recipes may have multiple published or house versions; identify source and version before comparing.',steps:['Read the listed source and distinguish an editorial study formula from a documented recipe.','Check family, method and ingredient roles before changing the spec.','Measure and execute the method; record exact result and products.','Compare sources respectfully and label adaptations as adaptations.'],trap:'A familiar drink name does not guarantee one canonical spec or verified origin.'},
'cobbler':{purpose:'A fruit-forward cobbler relies on fresh fruit aroma, measured sweetener and crushed-ice dilution.',steps:['Inspect and wash produce under approved prep rules; remove damaged fruit.','Build with the specified spirit/wine and sweetener, gently expressing fruit rather than pulverizing pith.','Use fresh crushed ice and a repeatable glass/portion; top as specified.','Taste as the ice melts and check the finish is not cloying.'],trap:'Fruit ripeness and water content vary; do not assume a garnish-heavy drink is automatically balanced.'},
'coffee':{purpose:'Coffee drinks balance extraction, temperature, sweetness and texture alongside the alcoholic base.',steps:['Use a fresh, consistent coffee extraction and measure it; espresso strength varies by recipe and machine.','Chill coffee before shaking when appropriate; use enough ice for controlled chilling and foam.','Check the modifier sweetness before adding extra syrup.','Verify dairy, egg, caffeine and other ingredient information; offer an appropriate alternative.'],trap:'A stable foam or “energy” description is not a safety claim; do not encourage alcohol/caffeine to mask impairment.'},
'hot drink':{purpose:'Hot serves need safe temperature, balanced dilution and careful handling of glass, steam and garnish.',steps:['Prewarm an approved heat-safe vessel and measure the recipe.','Use hot water or hot beverage at a controlled service temperature; avoid overfilling.','Add spirits and sweetener to the written spec, then stir and taste safely.','Warn about heat, present with a handle/sleeve if needed and check garnish stability.'],trap:'Never serve in chipped glass or use boiling liquid in unsuitable glassware.'},
'punch':{purpose:'Punch service scales a formula while preserving dilution, chill, flavor and responsible portioning.',steps:['Calculate batch yield from the approved per-serve recipe and measured portions.','Account for dilution separately; test a small service-size sample before batching.','Label batch contents, allergens, date/time, responsible preparer and approved discard/use-by per venue policy.','Keep at the required temperature and serve with a measured ladle/portion tool.'],trap:'Scaling ingredients linearly does not scale ice melt, aroma or balance; test the actual batch and service vessel.'},
'savory':{purpose:'Savory cocktails need clear control of salt, acid, spice and umami so seasoning supports—not overwhelms—the base.',steps:['Measure savory ingredients and check salt/sodium or allergen cues where relevant.','Add hot sauce, brine or seasoning in small measured increments.','Taste with the intended garnish and food context; dilution changes salt perception.','Record the exact product and spec; keep fresh savory ingredients under approved time/temperature control.'],trap:'“A dash” of brine or hot sauce is not standardized; over-seasoning cannot be repaired by guessing.'},
'spritz':{purpose:'A spritz balances a bitter or aromatic base, wine and sparkling lengthener while preserving bubbles.',steps:['Chill all components and the glass.','Measure the aperitivo and wine; add cold bubbles gently according to the house spec.','Use fresh ice if the recipe is on ice; lift once gently only if required.','Taste for bitterness, sweetness, acidity and dilution before adding garnish.'],trap:'A ratio is a starting spec, not a universal law; wine sweetness and aperitivo intensity vary by product.'},
'aperitivo highball':{purpose:'A bitter aperitivo in a highball depends on refreshing contrast, controlled sweetness and lively carbonation.',steps:['Measure bitter base and mixer against the recipe; check label strength and sweetness.','Build over fresh ice in a suitable glass and add cold bubbles last.','Lift gently once, then taste with a small sip.','Describe bitterness honestly and offer a lower-intensity alternative.'],trap:'A tall glass does not make an alcoholic drink low-strength; portion and actual ABV still matter.'},
'tropical bitter':{purpose:'Tropical fruit and bitter aperitivo need deliberate acid, sweet and dilution control to avoid a heavy, cloying drink.',steps:['Measure juice and bitter component; note whether the juice is fresh, sweetened or packaged.','Shake with consistent ice and strain over fresh ice if specified.','Taste after dilution for acidity, bitterness and finish separately.','Adjust one ingredient in a small measured step and update the costed spec.'],trap:'Do not add more juice or sugar to hide an imbalanced or overly strong pour.'}
};
const cocktailFamilyAliases={'equal-parts sour':'sour','modern sour':'sour','daisy':'sour','tiki sour':'tropical','aperitivo highball':'aperitivo highball','modern classic':'modern classic'};
function cocktailFamilyLab(c){const key=cocktailFamilyAliases[c.family]||c.family;const g=cocktailFamilyLabs[key]||cocktailFamilyLabs['modern classic'];return `<section class="detail-section cocktail-family-lab"><span class="eyebrow">TECHNIQUE LAB · ${esc(c.family)}</span><h3>Why this build works</h3><p>${esc(g.purpose)}</p><h3>Execute and diagnose</h3><ol>${g.steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol><div class="callout"><b>Common trap:</b> ${esc(g.trap)}</div></section>`}
function showCocktail(i){let c=cocktails[i];if(!c)return;let modal=$('#modal-root');let isKnown=knownNames.has(c.name)||Boolean(known[c.name])||Boolean(c.fromSource);let hasEditorialHistory=Boolean(known[c.name]);let ingredients=c.spec.split(';').map(part=>part.trim());modal.innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-head"><div><div class="eyebrow">${esc(c.family)} · ${esc(c.base)}</div><h2 style="font:600 30px 'Playfair Display';margin:6px 0">${esc(c.name)}</h2></div><button class="close" onclick="closeModal()">×</button></div><div class="pill-row" style="margin-bottom:15px"><span class="tag">${esc(c.glass)}</span><span class="tag gold">${esc(c.taste.split('.')[0])}</span><button class="btn btn-small" onclick="toggleFav(&quot;${esc(c.name)}&quot;);closeModal()">${store.favorites.includes(c.name)?'♥ Saved':'♡ Save favorite'}</button></div><div class="detail-layout"><div><section class="detail-section"><div style="display:flex;justify-content:space-between;align-items:center"><h3>House spec</h3><div class="measure-toggle"><button class="${measure==='oz'?'active':''}" onclick="setMeasure('oz',${i})">US oz</button><button class="${measure==='ml'?'active':''}" onclick="setMeasure('ml',${i})">ml</button></div></div><ul class="ingredients">${ingredients.map(item=>`<li><span>${esc(convertSpec(item,measure))}</span><span>•</span></li>`).join('')}</ul><section class="ingredient-role-card"><h3>What each line contributes</h3><ol>${ingredients.map((item,n)=>`<li><b>${esc(convertSpec(item,measure))}</b><span>${esc(ingredientRole(c,item,n))}</span></li>`).join('')}</ol><small>These are learning hypotheses from the ingredient names, not a substitute for the cited recipe source or approved house specification.</small></section><div class="lesson-block"><b>Method</b><p>${esc(c.method)}</p></div><div class="lesson-block"><b>Taste profile</b><p>${esc(c.taste)}</p></div><div class="lesson-block"><b>Glass & garnish</b><p>${esc(c.glass)} · ${esc(c.garnish)}. Choose a garnish that contributes aroma or a clear visual cue.</p></div></section>${cocktailFamilyLab(c)}</div><div><section class="detail-section"><h3>History & origin</h3><p>${esc(c.history)}</p><p><b>${esc(c.origin)}</b></p><div class="callout">${hasEditorialHistory?'Historical notes summarize commonly reported accounts; some origin claims remain debated.':c.source==='TheCocktailDB recipe listing'?'Recipe and instructions are sourced from TheCocktailDB; this listing does not establish a reliable creator, date or location. Treat origin stories as unverified.':c.source==='Family-template study spec'?'This is a clearly labeled family-based study formula, not a claim of a canonical archival recipe.':'An editorial starting spec is provided; check the adjacent history note for the strength of its origin attribution.'}</div></section><section class="detail-section"><h3>Build notes</h3><p>Balance sweet and sour by tasting. Citrus varies; ice, dilution, spirit proof and glass temperature all affect the final drink. Record your house adjustment below.</p><textarea class="price-input" rows="3" maxlength="3000" aria-label="Your tasting notes for ${esc(c.name)}" placeholder="Your tasting notes…" onchange="saveNote(&quot;${esc(c.name)}&quot;,this.value)">${esc(store.notes[c.name]||'')}</textarea></section></div></div><p style="font-size:9px;color:#89938b">Standard conversions: 1 US fl oz ≈ 29.57 ml. Recipe reference: ${esc(c.recipeReference||c.source||'Pourfolio study guide')}. Specs vary across publishers and bars; verify house standards, allergens and responsible-service requirements.</p></div></div>`}
function setMeasure(m,i){measure=m;showCocktail(i)}function convertSpec(text,m){if(m==='ml')return text.replace(/(\d+(?:\.\d+)?)\s*ml/g,(x,v)=>`${v} ml`).replace(/(\d+(?:\.\d+)?)\s*oz/g,(x,v)=>`${Math.round(Number(v)*29.57)} ml`);return text.replace(/(\d+(?:\.\d+)?)\s*ml/g,(x,v)=>`${(Number(v)/29.57).toFixed(Number(v)%29.57===0?0:2)} oz`)}function closeModal(){$('#modal-root').innerHTML=''}function saveNote(n,v){if(!cocktails.some(x=>x.name===n))return;store.notes[n]=String(v||'').slice(0,3000);if(save())toast('Tasting note saved')}
function spiritsPage(root){const spiritBrands={vodka:'Absolut (Sweden), Belvedere (Poland), Ketel One (Netherlands), Tito’s (United States) — examples across grain, potato and regional styles.',gin:'Beefeater and Tanqueray (London Dry examples), Plymouth Gin (distinct protected style), Hendrick’s (cucumber/rose-led modern style), Sipsmith (London craft example).',whiskey:'Scotch: Glenfiddich, Ardbeg; bourbon: Buffalo Trace, Maker’s Mark; rye: Rittenhouse; Irish: Redbreast, Jameson; Japanese: Nikka. Compare category and bottling, not just label.',rum:'Appleton Estate (Jamaican), Mount Gay (Barbadian), Wray & Nephew (Jamaican overproof), Rhum Clément (Martinique agricole), Flor de Caña (Nicaraguan). Styles differ widely.',brandy:'Cognac: Hennessy, Rémy Martin; Armagnac: Delord, Château de Laubade; Calvados: Christian Drouin; Spanish brandy: Fundador. Appellation and age rules differ.',tequila:'Tequila Ocho, El Tesoro, Herradura, Patrón — compare 100% agave bottlings, production choices and maturation; brand recipes vary.',mezcal:'Del Maguey, Los Siete Misterios, Nuestra Soledad — compare stated agave, village/producer and method; “smoky” is not a universal style.',cachaça:'Novo Fogo, Yaguara, Leblon — examples of Brazilian cachaça; compare unaged and wood-influenced bottlings.',pisco:'Peru: Barsol, Caravedo; Chile: Capel, Mistral — countries have distinct definitions and permitted styles.',aperitif:'Vermouth examples: Dolin, Noilly Prat, Carpano, Martini; bitter aperitivo examples: Campari, Aperol, Cynar. Refrigerate opened vermouth.'};const spiritStyleNotes={vodka:'Raw-material styles: wheat/rye can show grain spice; potato may feel rounder; grape or corn may differ in texture. These are tendencies, not guarantees. Flavoured vodka adds fruit/botanical character; compare label rules and actual product.',gin:'London Dry: juniper-led, dry and tightly regulated by category rules; botanicals generally distilled. Distilled gin: botanicals distilled with spirit, with more permitted finishing choices by jurisdiction. Compound gin: botanicals infused/blended rather than redistilled. Old Tom: often rounder or lightly sweetened. Plymouth: a protected regional style. Genever: malt-wine/grain spirit with juniper. Navy strength: higher proof, not a separate botanical recipe.',whiskey:'Scotch single malt: one distillery, malted barley; blended malt: multiple malt distilleries; blended Scotch: malt plus grain Scotch. Bourbon: US, minimum 51% corn and new charred oak. Rye: grain bill and local law vary; US straight rye requires at least 51% rye. Irish whiskey includes pot-still, malt and grain styles; triple distillation is common but not mandatory. Japanese whisky categories have local standards; verify current rules. Tennessee whiskey adds a charcoal-mellowing tradition under US rules.',rum:'Unaged white: clear, may be filtered after aging; aged/gold: time and wood vary. Molasses-based vs fresh cane-juice styles (rhum agricole is a protected French-Caribbean tradition); pot, column and blended stills; short-clean vs long/high-ester fermentation; overproof bottlings. “Dark” can reflect aging, blending or added color—check the producer.',brandy:'Cognac: protected French wine brandy, traditionally double pot-distilled and oak-aged; VS/VSOP/XO are regulated age categories. Armagnac: Gascony, commonly continuous-still or pot-distilled; rules differ. Calvados: Normandy apple/pear appellations. Brandy de Jerez: Spanish regional aging traditions. Pisco: Peru and Chile have separate rules. Grappa: Italian grape-pomace spirit. Eaux-de-vie: often clear fruit spirits.',tequila:'Blanco/plata: unaged or briefly rested; joven: blend/allowed treatment; reposado: at least 2 months in wood; añejo: at least 1 year; extra añejo: at least 3 years, subject to current CRT rules. 100% agave indicates sugars from blue Weber agave; mixto permits other sugars within the legal category. Oven/autoclave/diffuser extraction, fermentation and still choices affect profile.',mezcal:'Agave species and village/producer matter. Espadín is common, not the only agave. Joven is unaged; reposado and añejo are wood-aged categories. “Artesanal” and “ancestral” are regulated Mexican production classes with specific equipment/method requirements; they are not simple quality rankings. Smoke varies with cooking and distillation; it is not universal.',cachaça:'Brazilian cachaça is made from fermented fresh cane juice. Branca/prata is unaged or rested; aged styles use wood, including native Brazilian woods, which can add distinct color and aroma. Industrial and artisanal methods differ; cachaça is a distinct legal category, not simply a synonym for rum.',pisco:'Peruvian Puro uses one grape variety, Acholado blends varieties, and Mosto Verde distills partially fermented must under Peruvian rules. Chilean pisco uses separate denomination, grape, proof and aging rules. Ask which country and category before assuming a flavor profile.',aperitif:'Vermouth: fortified, aromatized wine in dry, bianco/blanc and sweet/rosso styles. Quinquina: aromatized wine with quinine-like botanicals. Gentian aperitifs emphasize root bitterness. Amaro is a broad bitter herbal liqueur family; red bitter aperitivo, alpine amaro and Fernet styles differ. Opened vermouth needs refrigeration.'};root.innerHTML=`<div class="content-intro"><div class="eyebrow">RAW MATERIAL · PROCESS · PLACE</div><h1 class="display">Spirits atlas.</h1><p class="lead">A bartender’s map from raw material to glass. Production laws differ by country; category terms below are educational summaries, not substitutes for local rules.</p></div><div class="filter-row">${spiritLessons.map(s=>`<button class="filter-chip" onclick="document.getElementById('sp-${s.key}').scrollIntoView({behavior:'smooth',block:'center'})">${s.name}</button>`).join('')}</div>${spiritLessons.map(s=>`<section class="detail-section" id="sp-${s.key}" style="margin-bottom:16px"><div class="title-row"><div><span class="tag gold">${s.tag}</span><h2 style="font:600 25px 'Playfair Display';margin:8px 0">${s.name}</h2></div><button class="link-btn" onclick="markComplete('${s.key}')">${store.completed.includes(s.key)?'✓ Studied':'Mark studied +'}</button></div><p>${s.summary}</p><div class="grid-3" style="margin-top:12px"><div class="lesson-block"><b>Production path</b><p>${s.production}</p></div><div class="lesson-block"><b>Flavor & tasting</b><p>${s.taste}</p></div><div class="lesson-block"><b>Styles & service</b><p><b>Styles:</b> ${s.types}<br><br><b>Service:</b> ${s.serve}</p></div></div><div class="lesson-block"><b>Styles & variations</b><p>${esc(spiritStyleNotes[s.key]||s.types)}</p></div><div class="callout"><b>Representative brand examples:</b> ${esc(spiritBrands[s.key]||'Examples vary by region and producer; compare the label and local definition.')} Treat these as tasting references, not endorsements; recipes and product profiles change by bottling and market.</div><div class="callout"><b>History & place:</b> ${s.origin}</div></section>`).join('')}<div class="topic-row"><article class="topic-card"><h3>Whiskey quick comparison</h3><div class="table-scroll"><table class="data-table"><thead><tr><th>Style</th><th>Grain / place</th><th>Usual profile</th><th>Useful cue</th></tr></thead><tbody><tr><td>Scotch single malt</td><td>Malted barley, one Scottish distillery</td><td>Fruit, malt, oak; peat varies</td><td>Single distillery ≠ single cask</td></tr><tr><td>Blended Scotch</td><td>Blend of malt and grain Scotch</td><td>Blender’s chosen balance</td><td>Can be excellent and intentional</td></tr><tr><td>Bourbon</td><td>US; at least 51% corn</td><td>Sweet grain, vanilla, oak</td><td>New charred oak required</td></tr><tr><td>Rye whiskey</td><td>US category: at least 51% rye</td><td>Pepper, herbs, dry spice</td><td>Other countries use distinct rules</td></tr><tr><td>Irish whiskey</td><td>Ireland; multiple mash/still styles</td><td>Fruit, cereal, gentle spice</td><td>Triple distillation is common, not universal</td></tr><tr><td>Single pot still</td><td>Ireland; malted + unmalted barley</td><td>Texture, spice, cereal</td><td>Distinct Irish tradition</td></tr></tbody></table></div></article><article class="topic-card"><h3>Brandy families</h3><ul><li><b>Cognac:</b> protected region in France; grape brandy, double distillation in copper pot stills, oak maturation.</li><li><b>Armagnac:</b> Gascony; often column-distilled (traditional continuous still), frequently expressive and single-vintage.</li><li><b>Calvados:</b> Normandy apple (and sometimes pear) brandy under appellation rules.</li><li><b>Brandy de Jerez:</b> Spanish brandy aged under regional rules, commonly in solera systems.</li><li><b>Pisco:</b> Peruvian and Chilean grape-spirit traditions, separately regulated.</li><li><b>Grappa:</b> Italian pomace spirit, made from grape skins/seeds/stems after winemaking.</li><li><b>Eau-de-vie:</b> Clear fruit brandy; orchard fruit, berries and stone fruit styles.</li></ul><p>Age labels and minimums are governed by appellation or country. Compare the actual label, not assumptions.</p></article></div><div class="section-head"><div><h2>Rum: production choices that matter</h2><p>“Light, gold, dark” tells you less than raw material, fermentation, still and maturation.</p></div></div><div class="table-scroll card"><table class="data-table"><thead><tr><th>Production choice</th><th>Typical effect</th><th>What to ask / taste</th></tr></thead><tbody><tr><td>Molasses</td><td>Can give caramel, dried fruit and deeper fermentation notes</td><td>How long was fermentation? What still?</td></tr><tr><td>Fresh cane juice</td><td>Often grassy, vegetal, floral or bright cane character</td><td>Is it an agricole-style or another regional cane spirit?</td></tr><tr><td>Short, clean fermentation</td><td>Cleaner, lighter congeners</td><td>Try in a Daiquiri or highball</td></tr><tr><td>Long / wild fermentation</td><td>May build fruity, funky ester complexity</td><td>Does the profile call for a bold mix or neat tasting?</td></tr><tr><td>Pot still</td><td>Often fuller, more characterful spirit</td><td>Look for weight and fermentation-driven aroma</td></tr><tr><td>Column still</td><td>Can produce a lighter, cleaner spirit; range is wide</td><td>Blending and cut decisions still matter</td></tr><tr><td>Barrel maturation</td><td>Oak, vanilla, spice, oxidation; tropical climates can mature quickly</td><td>Ask about age statements, climate, cask and additives</td></tr><tr><td>Blending / filtration</td><td>Can balance style, remove color or tailor texture</td><td>“Dark” color alone does not prove long aging</td></tr></tbody></table></div><div class="section-head"><div><h2>Tequila maturation labels</h2><p>Regulatory minimums are category-specific; check the current label and denomination.</p></div></div><div class="detail-list"><article class="mini-card"><b>Blanco / plata</b><small>Unaged or briefly rested within applicable rules; agave and fermentation character can be vivid.</small></article><article class="mini-card"><b>Reposado</b><small>Rested in wood for at least 2 months; agave may be joined by light vanilla and spice.</small></article><article class="mini-card"><b>Añejo</b><small>Aged at least 1 year in permitted oak containers; deeper oak, spice and dried-fruit cues.</small></article><article class="mini-card"><b>Extra añejo</b><small>Aged at least 3 years under category rules; oak can dominate, so taste agave presence carefully.</small></article><article class="mini-card"><b>100% agave</b><small>Fermentable sugars derive entirely from blue Weber agave under the regulated designation.</small></article><article class="mini-card"><b>Mezcal is broader</b><small>Different protected denomination, regions and agave species; production traditions are highly diverse and not always pit-roasted or smoky.</small></article></div><div class="callout">Sensory practice: nose gently, take a small sip, add a few drops of water if appropriate, then record aroma, sweetness, texture, alcohol warmth, finish and balance. Spit or decline tasting freely.</div>`}
function liqueurPage(root){let list=liqueurs.filter(l=>(`${l.name} ${l.category} ${l.taste}`.toLowerCase().includes(liqueurQuery.toLowerCase())));root.innerHTML=`<div class="title-row content-intro"><div><div class="eyebrow">THE MODIFIER CABINET · ${liqueurs.length} UNIQUE ENTRIES</div><h1 class="display">Liqueurs are flavor tools.</h1><p class="lead">Liqueur generally means a sweetened, flavored alcoholic product; recipes, base spirits and legal definitions vary. Use these notes as a tasting map, not a universal formula.</p></div><div class="search-box"><span>⌕</span><input id="liqueur-search" placeholder="Find a liqueur or flavor…" value="${esc(liqueurQuery)}"></div></div><div class="callout">Tasting protocol: pour a tiny measure, note aroma first, then sweetness, bitterness, texture and finish. Many products are brand names; profiles vary by bottling. Verify allergens and ABV on the label.</div><div class="filter-row">${[...new Set(liqueurs.map(l=>l.category))].map(c=>`<button class="filter-chip" onclick="document.querySelector('#liqueur-search').value='${esc(c)}';document.querySelector('#liqueur-search').dispatchEvent(new Event('input'))">${esc(c)}</button>`).join('')}</div><div class="detail-list">${list.map(l=>`<article class="mini-card"><span class="tag">${esc(l.category)}</span><b style="margin-top:8px">${esc(l.name)}</b><small>${l.examples?`<b>Brand examples:</b> ${esc(l.examples)}<br><br>`:''}<b>Profile:</b> ${esc(l.taste)}<br><br><b>Typical production:</b> ${esc(productionLiqueur(l.name))}<br><br><b>Try:</b> ${esc(l.use)}</small></article>`).join('')||'<div class="empty-state"><strong>No match</strong>Try a flavor or category.</div>'}</div>`;$('#liqueur-search').oninput=e=>{liqueurQuery=e.target.value;liqueurPage(root);let inp=$('#liqueur-search');inp.focus();inp.setSelectionRange(inp.value.length,inp.value.length)}}
function wineBeerPage(root){const grapeExamples={'Chardonnay':'Louis Jadot (Burgundy), Kumeu River (New Zealand), Rombauer (California)','Sauvignon Blanc':'Domaine Vacheron (Sancerre), Dog Point (Marlborough)','Riesling':'Dr. Loosen (Mosel), Trimbach (Alsace), Pewsey Vale (Australia)','Pinot Noir':'Domaine Drouhin (Oregon), Louis Jadot (Burgundy)','Cabernet Sauvignon':'Ridge (California), Château Lynch-Bages (Bordeaux)','Syrah / Shiraz':'E. Guigal (Rhône), Penfolds (Australia)','Tempranillo':'La Rioja Alta (Rioja), Vega Sicilia (Ribera del Duero)','Sangiovese':'Fontodi, Frescobaldi (Tuscany)','Chenin Blanc':'Domaine Huet (Loire), Ken Forrester (South Africa)','Grenache / Garnacha':'Alvaro Palacios (Spain), Château de Saint Cosme (Rhône)','Nebbiolo':'Vietti, G.D. Vajra (Piedmont)','Pinot Grigio / Gris':'Alois Lageder (Italy), Trimbach (Alsace)'};const beerExamples={'Pilsner':'Pilsner Urquell; Bitburger','Helles':'Augustiner-Bräu Helles; Weihenstephaner Original','Dunkel':'Ayinger Altbairisch Dunkel','Vienna lager':'Great Lakes Eliot Ness; Negra Modelo','Hefeweizen':'Weihenstephaner Hefeweissbier; Schneider Weisse','Belgian witbier':'Hoegaarden; Allagash White','Pale ale':'Sierra Nevada Pale Ale; Deschutes Mirror Pond','IPA':'Sierra Nevada Torpedo; Lagunitas IPA','West Coast IPA':'Stone IPA; Russian River Pliny the Elder','Hazy IPA':'Tree House Julius; Other Half examples','Porter':'Fuller’s London Porter; Deschutes Black Butte Porter','Stout':'Guinness Draught; North Coast Old Rasputin','Saison':'Saison Dupont; Fantôme Saison','Lambic / gueuze':'Cantillon; 3 Fonteinen; Boon','Sour ale':'Brouwerij Rodenbach; local mixed-fermentation examples','Barleywine':'Sierra Nevada Bigfoot; Anchor Old Foghorn (legacy example)','Kölsch':'Früh Kölsch; Gaffel Kölsch','Bock / Doppelbock':'Ayinger Celebrator; Einbecker Ur-Bock','Amber ale':'Bell’s Amber Ale; Alaskan Amber','Brown ale':'Samuel Smith’s Nut Brown Ale; Newcastle Brown Ale'};const wineProcess={'Still red':'Red grapes are crushed or destemmed and fermented with skins; cap management and maceration set color, tannin and extraction. Pressing, malolactic fermentation, vessel choice and oak shape body and aroma. Taste ranges from light/juicy to deeply tannic.', 'Still white':'Grapes are commonly pressed before fermentation; cool fermentation can preserve fruit, while skin contact, lees, malolactic fermentation and oak add texture. Styles range from crisp/high-acid to broad, creamy and barrel-influenced.',Rosé:'Direct pressing or brief skin contact produces pale to deeper pink wines; fermentation can be cool and protective. Blending is allowed in some regions/styles and restricted in others. Dryness and fruit vary.', 'Orange / skin-contact':'White grapes ferment with some skin contact, extracting color, aroma and tannin; maceration can be days to months. Taste can be grippy, savory, amber-fruited or very light—“orange” is a method family, not one flavor.',Sparkling:'Traditional method: second fermentation in bottle with lees aging; tank method: second fermentation in pressurized tank to emphasize fresh fruit; other permitted methods include transfer and carbonation. Dosage, pressure and lees time change sweetness and texture.',Fortified:'Spirit is added to wine at different stages. Port fortification can retain grape sugar; Sherry uses region-specific aging including flor/oxidative systems; Madeira is heated/oxidized under its rules; vermouth is fortified and aromatized. These are not interchangeable styles.', 'Dessert / sweet':'Sweetness can come from late harvest, noble rot, drying/concentration, freezing in permitted contexts, or stopping fermentation. Good examples balance residual sugar with acidity and sometimes bitterness.', 'Low / no alcohol':'Some wines are fermented normally and then dealcoholized (vacuum, membrane or related technologies); others manage fermentation. Aroma and body can shift, so read the label and taste the actual product.'};const beerProcess={'Pilsner':'Pale malt, cool lager fermentation and assertive but clean hop expression; careful conditioning gives a crisp finish. Czech and German traditions differ in water, malt and hop profile.',Helles:'Pale malt-led lager with restrained bitterness; fermentation and cold conditioning emphasize a soft, clean finish.',Dunkel:'Lager made with darker Munich-style malts; kilning and grist add bread crust, toast and caramel without requiring heavy roast.', 'Vienna lager':'Amber lager built around toasted Vienna-style malt with measured hop bitterness; modern interpretations vary.',Hefeweizen:'High wheat grist and top-fermenting yeast; yeast-derived banana/clove notes depend on strain and fermentation. Often bottle-conditioned; pour and sediment practice varies.', 'Belgian witbier':'Wheat-based pale ale, often with coriander and citrus peel; yeast can add spice and fruit. Recipes vary by brewery.', 'Pale ale':'Ale fermentation with pale malt and balanced hop additions; bitterness, aroma and color vary by regional school.',IPA:'India Pale Ale is a broad hop-forward family. Bittering additions, late hops and dry hopping shape resin, citrus or tropical aromas; alcohol and malt balance vary.', 'West Coast IPA':'Typically dry and relatively clear, with firm bitterness and pronounced hop aroma; modern examples may be less bitter. Water, yeast and hop timing matter.', 'Hazy IPA':'Often uses wheat/oats and late/dry hopping for soft body and saturated hop aroma. Haze is not a freshness guarantee; handle cold and minimize oxygen.',Porter:'Ale family using roasted/brown malts for cocoa, toast and coffee. Historical porter styles are diverse; malt bill, fermentation and strength drive the result.',Stout:'Dark ale with roasted barley/malts; dry Irish stout, oatmeal, milk/sweet stout and imperial stout differ in grist, body and residual sweetness.',Saison:'Farmhouse ale family often highly attenuated and dry; expressive yeast, spice and sometimes mixed fermentation shape aroma.', 'Lambic / gueuze':'Belgian lambic uses spontaneous fermentation and mixed microbes with extended maturation; gueuze blends young and old lambics and bottle-ferments. Tartness and funk vary by producer and age.', 'Sour ale':'Broad modern family: kettle-soured beers use controlled acidification before boiling; mixed-culture and fruit-aged beers use longer microbial maturation. Sourness alone does not define quality.',Barleywine:'High-gravity ale with concentrated malt, long boil and substantial maturation potential; American examples may be hop-forward, English examples malt-rich.',Kölsch:'Protected Cologne style: top-fermented ale followed by cool conditioning, balancing delicate fruit with crisp lager-like finish.', 'Bock / Doppelbock':'Strong malt-forward lager family. Doppelbock is generally stronger/richer; malt kilning, yeast and lagering create bread, caramel or dark-fruit cues.', 'Amber ale':'Ale with amber/colorful malt and moderate hops; caramel/toast notes depend on grist and fermentation.', 'Brown ale':'Ale featuring brown/roasted malts for nut, cocoa and caramel notes; regional examples vary in sweetness and hop bitterness.'};root.innerHTML=`<div class="content-intro"><div class="eyebrow">FERMENTATION · PLACE · STYLE</div><h1 class="display">Wine & beer, with context.</h1><p class="lead">Two ancient fermented beverage families. Understand the process, then listen to what the glass is telling you.</p></div><div class="section-head"><div><h2>Wine: from vineyard to bottle</h2><p>Climate, grape, decisions in the cellar and time build the style.</p></div></div><div class="grid-2"><article class="topic-card"><h3>How wine is made</h3><ol><li>Choose variety, site and harvest moment; ripeness affects sugar, acidity, flavor and tannin.</li><li>Sort and crush/destem (or whole-cluster); white wines are often pressed before fermentation, reds commonly ferment with skins.</li><li>Yeast ferments grape sugar into alcohol and carbon dioxide. Temperature and vessels shape aroma and texture.</li><li>Red wine gains color and tannin from skin contact. Rosé gets brief maceration or other legal methods; orange wine ferments white grapes with skins.</li><li>Press, mature in tank/barrel/concrete or on lees; blending and malolactic fermentation are optional choices.</li><li>Clarify/stabilize as desired, bottle, and allow appropriate development. Sweetness may remain or be adjusted under local rules.</li></ol></article><article class="topic-card"><h3>What shapes taste?</h3><ul><li><b>Climate:</b> cooler sites often retain acidity and slower ripening; warmer sites often achieve riper fruit and higher potential alcohol (exceptions abound).</li><li><b>Soil, aspect & water:</b> influence vine growth, drainage and ripening; avoid saying the wine literally tastes of a rock.</li><li><b>Grape & canopy:</b> variety, yields, exposure, disease pressure and harvest selection matter.</li><li><b>Cellar choices:</b> yeast, extraction, temperature, oxygen, vessel, oak, lees and blending.</li><li><b>Vintage & aging:</b> season and bottle evolution alter structure and aroma.</li><li><b>Service:</b> temperature, glass shape, air and food change perception.</li></ul></article></div><div class="grid-2" style="margin-top:14px"><article class="topic-card"><span class="tag gold">A SHORT WINE HISTORY</span><h3 style="margin-top:10px">From ancient fermentation to appellation</h3><p>Archaeological evidence places early grape-wine production in the South Caucasus and Near East thousands of years ago; a frequently cited Georgian site dates to roughly 6000 BCE, but “oldest evidence” is not proof of one invention point. Phoenician, Greek and Roman trade helped spread viticulture around the Mediterranean. Monastic communities later preserved and developed vineyard knowledge in parts of Europe. Modern science, transport, glass bottles, cork and appellation systems reshaped production and trade. Today wine is made on every inhabited continent with many local traditions.</p></article><article class="topic-card"><span class="tag gold">A SHORT BEER HISTORY</span><h3 style="margin-top:10px">Grain, fermentation & the brewing revolution</h3><p>Fermented grain beverages predate modern records, and archaeological interpretations continue to develop. Beer became central to ancient Mesopotamian and Egyptian foodways; the Sumerian Hymn to Ninkasi (second millennium BCE) preserves a brewing-related text. Brewing knowledge traveled through Europe and beyond. Industrial-scale malting, thermometers, refrigeration, pure yeast cultures and pasteurization transformed consistency in the 19th century; craft and regional brewing later diversified styles. The story is global, not exclusively European.</p></article></div><div class="section-head"><div><h2>Wine styles</h2><p>Production choices define the broad family; grape and place add detail.</p></div></div><div class="grid-4">${wineStyles.map(x=>`<article class="card"><h3>${x[0]}</h3><p>${x[1]}</p><small><b>Production to profile:</b> ${esc(wineProcess[x[0]]||'Methods vary by producer; taste the bottle.')}</small></article>`).join('')}</div><div class="section-head"><div><h2>Wine regions to recognize</h2><p>Signature grapes and styles—broad signposts, not rigid rules.</p></div></div><div class="grid-3">${[['France','Champagne (sparkling); Burgundy (Pinot Noir, Chardonnay); Bordeaux (Cabernet/Merlot blends); Loire (Sauvignon Blanc, Chenin Blanc); Rhône (Syrah, Grenache).'],['Italy','Tuscany (Sangiovese); Piedmont (Nebbiolo); Veneto (Prosecco, Amarone); Sicily and Etna (diverse native grapes).'],['Spain & Portugal','Rioja/Ribera (Tempranillo); Rías Baixas (Albariño); Sherry/Jerez; Douro (Port and table wine); Vinho Verde.'],['Germany & Austria','Mosel/Rheingau Riesling; Austria Grüner Veltliner and Blaufränkisch; dry through sweet styles.'],['Americas','Napa/Sonoma (Cabernet, Chardonnay); Oregon (Pinot Noir); Chile (Cabernet, Carmenère); Argentina (Malbec); Uruguay (Tannat).'],['Southern Hemisphere','Marlborough Sauvignon Blanc; Barossa Shiraz; Central Otago Pinot; South Africa Chenin Blanc and Pinotage.']].map(a=>`<article class="card"><h3>${a[0]}</h3><p>${a[1]}</p></article>`).join('')}</div><div class="section-head"><div><h2>Grape field notes</h2><p>Use as a first hypothesis; style and producer make the final call.</p></div></div><div class="table-scroll card"><table class="data-table"><thead><tr><th>Grape</th><th>Typical cues & important regions</th></tr></thead><tbody>${wineGrapes.map(g=>`<tr><td><b>${g[0]}</b></td><td>${g[1]}<br><br><b>Producer examples:</b> ${esc(grapeExamples[g[0]]||'Examples vary by region.')} (illustrative; profiles differ by bottling)</td></tr>`).join('')}</tbody></table></div><div class="section-head"><div><h2>Wine language</h2><p>Precise words make recommendations more useful.</p></div></div><div class="detail-list">${wineTerms.map(t=>`<article class="mini-card"><b>${t[0]}</b><small>${t[1]}</small></article>`).join('')}</div><div class="section-head"><div><h2>Beer: grain, hops, yeast & water</h2><p>Fermentation and conditioning set the family; ingredients and process define the style.</p></div></div><div class="grid-2"><article class="topic-card"><h3>Brewing in six steps</h3><ol><li><b>Malting:</b> grain is steeped, germinated, then kilned; malt provides enzymes, fermentable extract, color and flavor.</li><li><b>Mashing:</b> crushed malt mixes with warm water; enzymes convert starch into sugars.</li><li><b>Lautering:</b> sweet wort separates from grain; sparging rinses remaining extract.</li><li><b>Boiling:</b> wort is boiled, hops add bitterness/flavor/aroma; timing affects extraction and volatile oils.</li><li><b>Fermentation:</b> yeast converts sugars into alcohol, CO₂ and flavor compounds. Ales often use warmer fermentations; lagers typically use lager yeast and cool fermentation/conditioning.</li><li><b>Conditioning & package:</b> clarify, mature, carbonate and package; oxygen control is crucial for freshness.</li></ol></article><article class="topic-card"><h3>How to taste beer</h3><p>Look at color and foam; smell before sipping; notice first impression, malt/hop balance, bitterness, carbonation, body and finish. Serve styles at suitable—not ice-numbingly cold—temperatures.</p><div class="callout">Beer history spans ancient grain fermentation across multiple civilizations. The modern ale/lager distinction reflects yeast and process, but is not a simple “top vs bottom” rule for every fermentation.</div></article></div><div class="section-head"><div><h2>Beer style map</h2><p>Examples for recognizing the range.</p></div></div><div class="detail-list">${beerStyles.map(s=>`<article class="mini-card"><b>${s[0]}</b><small>${s[1]}<br><br><b>Production to profile:</b> ${esc(beerProcess[s[0]]||'Fermentation and recipe vary by producer.')}<br><br><b>Producer examples:</b> ${esc(beerExamples[s[0]]||'Producer and style vary by region.')} (illustrative; verify the current product and style)</small></article>`).join('')}</div><div class="callout">Glassware: a wine glass or tulip helps aroma; a flute or coupe showcases sparkling wine but a universal “correct” glass doesn’t exist. Beer glass shapes can support foam and aroma; a clean, appropriate glass and pour matter more than collecting every shape.</div>`}
function pairingPage(root){let select=gameState.pairSpirit||'All';let data=select==='All'?pairings:pairings.filter(p=>p.spirit===select);root.innerHTML=`<div class="content-intro"><div class="eyebrow">FLAVOR LOGIC · FOOD & DRINK</div><h1 class="display">Pairing studio.</h1><p class="lead">30 pairing prompts for each of 10 spirit families. Use echo, contrast and bridge as your three tools; the best pairing is always tasted, not assumed.</p></div><div class="filter-row">${['All',...spiritLessons.map(s=>s.name)].map(s=>`<button class="filter-chip ${select===s?'active':''}" onclick="gameState.pairSpirit='${s}';pairingPage(document.querySelector('#app-content'))">${s}</button>`).join('')}</div><div class="callout">Technique: first identify the dish’s dominant flavor, fat, heat, texture and intensity. Then match intensity; choose a drink that echoes a flavor, contrasts the dish (acid/bitterness/bubbles), or bridges via a shared aroma. Consider temperature, sweetness, alcohol heat and cultural context respectfully.</div><div class="pill-row" style="margin:14px 0"><span class="tag">${data.length} ideas</span><span class="tag gold">30 examples per spirit</span></div><div class="pairing-grid">${data.map((p,i)=>`<article class="pair-card"><span class="tag">${p.tech.split(':')[0]}</span><b style="margin-top:8px">${esc(p.spirit)} + ${esc(p.food)}</b><p>${esc(p.why)}<br><br><b>Technique:</b> ${esc(p.tech.split(': ')[1])}</p></article>`).join('')}</div><div class="section-head"><div><h2>Cocktail, beer & wine with world cuisines</h2><p>Starting points—adjust for the actual dish, spice level and preparation.</p></div></div><div class="grid-3">${[['Nepal','Momo (steamed/fried)','Bright ginger-lime highball or crisp lager; acidity and bubbles refresh rich fillings; match chili sauce separately.'],['Japan','Sushi / tempura','Dry sake, crisp lager or gin highball; clean finish and carbonation complement delicate fish and fried texture.'],['Mexico','Tacos al pastor','Blanco tequila Paloma or pale lager; citrus and grapefruit cut pork richness, agave echoes salsa.'],['India','Tandoori / curry','Off-dry Riesling, wheat beer or citrus-forward sour; aromatic fruit softens heat and acidity lifts spice-rich sauces.'],['Italy','Tomato pasta / pizza','Sangiovese or spritz; lively acidity meets tomato, while bitterness can refresh cheese and oil.'],['France','Roast chicken / cheese','Chardonnay, Pinot Noir or dry cider; match oak/body to roast and use acidity to reset the palate.'],['Thailand','Green curry','Lager, off-dry Riesling or lime-coconut rum highball; sweetness eases chile while citrus echoes herbs.'],['Korea','Korean fried chicken','Pilsner or sparkling wine; bubbles and bitterness cleanse crisp coating, sweetness can bridge spicy glaze.'],['Ethiopia','Injera & lentil stew','Amber beer or fruity red; malt echoes toasted bread, fruit can soften berbere heat.'],['Peru','Ceviche','Pisco Sour (less sweet) or crisp Sauvignon Blanc; citrus and acidity echo the leche de tigre; keep alcohol moderate.'],['United States','BBQ brisket','Bourbon Old Fashioned or porter; oak/caramel echoes char, bitter/roast notes cut fat.'],['China','Dim sum','Jasmine highball, Riesling or lager; bubbles and aromatic lift complement varied savory bites.']].map(x=>`<article class="card"><span class="tag gold">${x[0]}</span><h3 style="margin-top:10px">${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div>`}
function craftPage(root){root.innerHTML=`<div class="content-intro"><div class="eyebrow">FORMULA · ITERATION · MARGIN</div><h1 class="display">Create your signature.</h1><p class="lead">Design with a structure, not a guess. Balance is a conversation among sweetness, acidity, bitterness, alcohol, dilution, temperature and aroma.</p></div><div class="grid-2"><article class="topic-card"><h3>A six-step development loop</h3><ol><li><b>Start with a story or ingredient.</b> Choose one clear idea: seasonal fruit, a local herb, a spirit, or a flavor memory.</li><li><b>Choose a family.</b> Sour (spirit + citrus + sweetener), Old Fashioned (spirit + sugar + bitters), Martini/Manhattan (spirit + fortified wine), highball (spirit + lengthener), or spritz/fizz.</li><li><b>Choose a base spirit.</b> Be specific about proof, style and intensity. Decide whether it leads or supports.</li><li><b>Build a measured first draft.</b> For a sour, try 60 ml spirit, 25 ml citrus, 15–20 ml sweetener; shake, strain and taste. For a stirred drink, start with 60 ml spirit and 20–30 ml modifier.</li><li><b>Change one variable at a time.</b> Too sharp? Tiny sweetener adjustment. Flat? Acid, salt or bitter lift. Hot? Check proof, dilution, temperature and serving size before adding sugar.</li><li><b>Record, cost and repeat.</b> Test with your actual ice, glass, garnish and service speed. Name only after the drink is stable.</li></ol><div class="callout">A balanced drink is not necessarily equal parts or universally liked. The guest, context and ingredient quality matter.</div></article><article class="topic-card"><h3>Balance checklist</h3><div class="metric-line"><span>Sweetness</span><strong>Roundness · body · aromatic carry</strong></div><div class="metric-line"><span>Acidity</span><strong>Lift · salivation · contrast</strong></div><div class="metric-line"><span>Bitterness</span><strong>Structure · length · appetite</strong></div><div class="metric-line"><span>Alcohol</span><strong>Weight · warmth · aroma solvent</strong></div><div class="metric-line"><span>Dilution</span><strong>Integration · temperature · texture</strong></div><div class="metric-line"><span>Aroma</span><strong>First impression · garnish · glass</strong></div><div class="metric-line"><span>Salt / umami</span><strong>Can amplify flavor; use sparingly</strong></div><p style="margin-top:14px">Taste at serving temperature. A straw taste can overstate sweetness or alcohol; use a clean spoon or sample pour. Document the exact spec and method.</p></article></div><div class="section-head"><div><h2>Drink costing calculator</h2><p>Cost each pour from your purchase unit; never mistake markup for margin.</p></div></div><div class="grid-2"><article class="topic-card"><h3>Build a quick estimate</h3><label>Purchase price (currency units)<input class="price-input" id="cost-price" type="number" step="0.01" min="0" value="${gameState.costPrice||30}"></label><label>Bottle volume (ml)<input class="price-input" id="cost-volume" type="number" step="1" min="1" value="${gameState.costVolume||750}"></label><label>Pour used (ml)<input class="price-input" id="cost-pour" type="number" step="1" min="1" value="${gameState.costPour||45}"></label><label>Other ingredients + garnish cost<input class="price-input" id="cost-other" type="number" step="0.01" min="0" value="${gameState.costOther||15}"></label><label>Target beverage cost %<input class="price-input" id="cost-target" type="number" step="0.1" min="1" max="100" value="${gameState.costTarget||22}"></label><button class="btn" onclick="calculateCost()">Calculate</button><div id="cost-result" class="lesson-block" style="margin-top:14px" aria-live="polite">Enter your local costs to see a suggested menu price.</div></article><article class="topic-card"><h3>Formula & operating notes</h3><p><b>Liquor cost per pour</b> = purchase price ÷ bottle volume × pour volume.</p><p><b>Drink cost</b> = all ingredient costs + garnish/consumable allocation. Include waste and breakage in your broader inventory model.</p><p><b>Target price</b> = drink cost ÷ target beverage-cost fraction. Example: cost 2.20 ÷ 0.22 = 10.00 before taxes/service charges and local pricing strategy.</p><p><b>Pour-cost %</b> = drink cost ÷ menu price × 100. This is not gross margin and does not include labor, rent, tax or overhead.</p><div class="callout">Use your actual invoice, yield, standard pour, comp/spill policy and local tax rules. Cost targets vary by venue and product mix.</div></article></div>`}
function calculateCost(){const p=Number($('#cost-price').value),v=Number($('#cost-volume').value),u=Number($('#cost-pour').value),o=Number($('#cost-other').value),percent=Number($('#cost-target').value),t=percent/100,result=$('#cost-result');if(![p,v,u,o,percent].every(Number.isFinite)||p<=0||v<=0||u<=0||u>v||o<0||percent<1||percent>100){result.textContent='Check the inputs: bottle price and volume must be positive, pour must be positive and no larger than the bottle, other cost non-negative, and target between 1% and 100%.';return}const spiritCost=p/v*u,cost=spiritCost+o,price=cost/t;if(!Number.isFinite(cost)||!Number.isFinite(price)){result.textContent='These values are outside the calculator range. Check the units and amount.';return}result.innerHTML=`<b>Estimated drink cost: ${cost.toFixed(2)}</b><p>Spirit pour: ${spiritCost.toFixed(2)} · Other ingredients: ${o.toFixed(2)}<br>At ${percent}% target cost, suggested base price: <b>${price.toFixed(2)}</b><br>At a menu price of ${price.toFixed(2)}, estimated pour cost: ${((cost/price)*100).toFixed(1)}%</p>`}
const serviceTopics=[['Free pour: train, then verify','Free-pouring is a measured skill, not a shortcut around control. Use a consistent spout, bottle angle, count cadence and pour size; calibrate with a jigger or scale. A “four-count” is not a universal ml measure—flow depends on bottle, liquid, spout, temperature and technique. Practice over a graduated measure, compare count to target, log errors, and recheck regularly. Follow venue policy and local law; use measured pours where required.'],['Inventory & stock control','Create a master item list (SKU, brand, size, cost, supplier, par). Count opening and closing stock consistently; track deliveries, transfers, comps, waste and breakage. Use FIFO (first in, first out), date open bottles/prep, store vermouth refrigerated, and rotate perishables. Compare theoretical usage from POS recipes with actual depletion; investigate variance without blame. Set par from lead time and sales velocity, not habit.'],['Stocking & mise en place','Forecast by daypart, reservations, events, season and weather. Prep only safe, forecasted quantities; label item, prep date/time, use-by and initials. Keep backup stock accessible but secure. Check glassware, ice, garnishes, syrups, juices, coffee, non-alcoholic options, tools, sanitation and cash/POS before service. Use a closing checklist and communicate 86’d items.'],['Taking an order & serving','Welcome promptly; ask open questions about flavor, spirit, sweetness, alcohol strength and dietary/allergen needs. Repeat the order, clarify modifications, confirm age/ID per law, and communicate wait time. Serve from the guest’s right if venue protocol specifies; present safely, identify the drink and garnish, and check back naturally. Never pressure a guest to drink or upsell beyond their comfort.'],['Communication & hospitality','Use attentive listening, names only when welcome, clear language and calm body posture. Translate technical details into guest-friendly cues. Offer choices without judgment. Coordinate with floor and kitchen; repeat critical allergy and timing information. Read the room, respect boundaries and include non-drinkers with equally thoughtful options.'],['Difficult situations & safety','Stay calm, lower the temperature, listen and acknowledge the concern. State what you can do, offer a fair next step and involve a manager early when needed. Follow venue policy for refusal of service, intoxication, harassment, violence and medical emergencies. Do not physically restrain or argue; prioritize safety, document facts and contact security/emergency services as appropriate. Never serve someone visibly intoxicated where prohibited.'],['Overcoming fear & confidence','Prepare a short welcome, learn a small set of reliable specs, rehearse one recommendation, and ask one clarifying question at a time. Use a breath before responding. Treat mistakes as information: correct promptly, tell a lead, and note how to prevent repeat. Confidence grows from practice, feedback and a supportive team—not pretending to know everything.'],['Menu development & design','Begin with concept, guests, price point, season, equipment, staffing and legal constraints. Create category variety across base spirit, flavor, strength, method and price. Standardize recipes in ml and oz, specify brands only when essential, include allergens/ABV cues where appropriate, test for speed and dilution, cost every spec, photograph consistently and train the team. Review sales mix and guest feedback; remove complexity that does not earn its place.'],['Bar / restaurant business terms','COGS: cost of goods sold. Pour cost: beverage cost divided by sales. Prime cost: labor + COGS. Gross margin: sales less direct costs. Covers: guests served. Average check: sales per guest/check. RevPASH: revenue per available seat-hour. Par: target stock level. Variance: actual vs theoretical usage. Comp: authorized no-charge item. Void: canceled transaction under policy. 86: item unavailable. Yield: usable output after trim/loss. Menu mix: sales distribution by item.'],['Bartender / server terms','Mise en place: everything prepared and in place. Well/call/premium: venue-specific spirit tiers. Neat: spirit without ice/water; on the rocks: over ice; up: chilled and strained without ice; build: assemble in serving glass; double strain: fine-strain to catch solids. Back: small side drink; chaser: separate follow-up. Ticket: order. Rail: speed-well spirits. Sidework: opening/closing tasks. Check-back: guest follow-up. Always confirm house meaning—terms differ.'],['Responsible service & inclusion','Check age identification under local rules. Understand legal limits, standard drink definitions and venue policies. Offer water, food and alcohol-free choices. Do not make medical claims or encourage rapid consumption. Be respectful across cultures, identities and abilities; ask before assuming. If unsure about a legal or safety decision, pause and consult the manager.']];
function servicePage(root){root.innerHTML=`<div class="content-intro"><div class="eyebrow">THE HUMAN SIDE OF THE BAR</div><h1 class="display">Hospitality is a craft.</h1><p class="lead">Technical skill matters. So do clear communication, safe service, thoughtful systems and the confidence to ask for help.</p></div><div class="topic-row">${serviceTopics.map((x,i)=>`<article class="topic-card"><span class="tag">FIELD NOTE ${String(i+1).padStart(2,'0')}</span><h3 style="margin-top:10px">${x[0]}</h3><p>${x[1]}</p><button class="link-btn" onclick="markComplete('svc${i}')">${store.completed.includes('svc'+i)?'✓ Practiced':'Mark reviewed +'}</button></article>`).join('')}</div><div class="callout"><b>For your own confidence:</b> keep a small shift journal—one win, one question, one practice target. Never place guest safety or local law below sales goals.</div>`}
const toolsList=[['Jigger','Measures repeatable volume. Use the marked line or calibrate; a jigger protects balance and cost.'],['Shaker tin set','Boston or cobbler styles. Shake citrus, juice, dairy/egg and many syrups; chill and dilute with control.'],['Mixing glass & bar spoon','For spirit-forward cocktails. Stir to temperature and dilution; keep the spoon bowl against the glass wall.'],['Hawthorne strainer','Coiled strainer for shaker tins; hold securely and control the pour.'],['Fine strainer','Catches ice chips, pulp and herb fragments in a double strain.'],['Julep strainer','Traditional bowl strainer, often used with a mixing glass.'],['Muddler','Gently express oils and soft fruit. Avoid pulverizing mint into bitter fragments.'],['Bar knife & peeler','Sharp, safe tools for clean citrus cuts and expressive twists; cut away from the body.'],['Citrus press / juicer','Fresh juice improves aroma; strain seeds and label/date batches.'],['Pour spouts','Consistent flow tools; clean, dry and calibrate. Never assume a count equals a fixed volume.'],['Ice scoop & tongs','Use dedicated clean tools; never handle service ice by hand or use glassware as an ice scoop.'],['Scale & thermometer','Useful for batching, prep ratios, syrup consistency and safe temperature control.'],['Speed rail & bottle mats','Arrange high-use bottles ergonomically; use spill mats, labels and safe bottle handling.'],['Dishwasher / glass polisher','Use the venue’s wash-rinse-sanitize process; inspect for lipstick, detergent residue, chips and cracks.']];
const glassList=[['Coupe','Short shaken/stirred drinks served up; broad rim supports aroma.'],['Nick & Nora','Small stemmed glass for a neat, chilled cocktail; elegant and practical capacity.'],['Martini / cocktail glass','Classic stemmed serve; chill well and mind capacity to preserve temperature.'],['Rocks / Old Fashioned','Short drinks over ice; broad base suits large cubes and aromatic garnish.'],['Double rocks','More volume for larger pours or long ice; still measure responsibly.'],['Highball','Tall glass for spirit + lengthener; enough room for ice and carbonation.'],['Collins','Tall, narrow glass often used for longer citrus drinks and fizz.'],['Coupe / sour glass','Stemmed vessel for shaken sours; avoid overfilling and spill risk.'],['Flute / tulip','Sparkling wine; tulip shape often offers more aroma than a narrow flute.'],['Wine glass','Bowl shape captures aromas; shape/size chosen to style and service.'],['Snifter / tulip tasting','Brandy and aromatic spirits; smaller pours and gentle nosing.'],['Beer tulip / goblet','Supports foam and aromatic beer styles; clean glass is essential.'],['Pilsner glass','Tall tapered form highlights clarity and carbonation.'],['Mug / tankard','Insulated, sturdy beer presentation; keep impeccably clean.'],['Hurricane','Curved long-drink glass; visually associated with tropical serves.']];
function toolsPage(root){root.innerHTML=`<div class="content-intro"><div class="eyebrow">YOUR STATION · YOUR SERVICE</div><h1 class="display">Tools & glassware.</h1><p class="lead">Choose the right tool for control, consistency and safety. Equipment is useful only when clean, maintained and used with purpose.</p></div><div class="section-head"><div><h2>Bar tools & equipment</h2><p>Core station kit and what each piece does.</p></div></div><div class="detail-list">${toolsList.map(t=>`<article class="mini-card"><b>${t[0]}</b><small>${t[1]}</small></article>`).join('')}</div><div class="section-head"><div><h2>Glassware guide</h2><p>Match the glass to temperature, aroma, volume and guest experience.</p></div></div><div class="detail-list">${glassList.map(t=>`<article class="mini-card"><b>${t[0]}</b><small>${t[1]}</small></article>`).join('')}</div><div class="callout">Safety and sanitation: inspect glassware for chips, cracks and residue; keep glass out of ice wells; store tools dry; follow your local food-safety rules for cleaning, sanitizer concentration and prep dating.</div>`}
const quizBank=[
{q:'Which balance formula best describes a classic Daiquiri?',a:['Rum, lime and sugar','Gin, vermouth and bitters','Whiskey, coffee and cream','Tequila, tomato and celery'],c:0,why:'A Daiquiri is a rum sour: spirit, fresh lime and sweetener.'},
{q:'What does a jigger primarily improve?',a:['Carbonation','Repeatable measurement and cost control','Ice dilution only','Glass temperature'],c:1,why:'Consistent measurement protects the recipe, responsible serving and beverage cost.'},
{q:'Which is the defining botanical in gin?',a:['Coriander','Juniper','Angelica','Cardamom'],c:1,why:'Juniper is the defining botanical; many other botanicals can support it.'},
{q:'What is the central raw material for tequila?',a:['Blue Weber agave','Sugar beet','Barley malt','Grapes'],c:0,why:'Tequila is made from blue Weber agave in designated Mexican regions.'},
{q:'Which choice generally adds fresh acidity to a cocktail?',a:['Fresh citrus juice','More ice only','A large garnish pick','Higher-proof spirit'],c:0,why:'Citrus brings acidity; dilution and temperature affect balance but are not acidity.'},
{q:'What does FIFO mean in stock rotation?',a:['First in, first out','Fast inventory for orders','Final invoice from outlet','Fresh ice for operations'],c:0,why:'Use older dated stock before newer stock, assuming it remains safe and in quality.'},
{q:'Which is a better origin-history practice?',a:['Present the most famous story as fact','Flag uncertain or competing origin claims','Invent an exact date','Avoid history altogether'],c:1,why:'Cocktail lore often has competing stories. Be clear about what is documented vs folklore.'},
{q:'Why keep opened vermouth refrigerated?',a:['It is aromatized wine and can oxidize','It freezes at room temperature','It becomes distilled spirit','It loses all alcohol immediately'],c:0,why:'Vermouth is wine-based; refrigeration slows oxidation and quality loss.'},
{q:'Which technique is generally used for a citrus-forward sour?',a:['Shake with ice','Stir without ice','Build in a warm glass','Blend dry only'],c:0,why:'Shaking chills, dilutes and aerates citrus-containing cocktails.'},
{q:'For a stirred Martini-style drink, what should you focus on?',a:['Warmth and foam','Cold temperature and controlled dilution','Maximum citrus juice','Crushed ice in the coupe'],c:1,why:'A stirred spirit-forward cocktail is about chilling and controlled dilution.'},
{q:'Which pairing principle uses shared aromas to connect dish and drink?',a:['Bridge','Contrast only','FIFO','Proofing'],c:0,why:'A bridge ingredient (herb, spice, fruit) connects flavors in the dish and drink.'},
{q:'What does “single malt Scotch” broadly identify?',a:['One grain type from one distillery in Scotland','One cask from any country','A blend of only corn whiskey','An unaged Scotch'],c:0,why:'Single malt Scotch is malt whisky from one Scottish distillery; it may blend multiple casks.'},
{q:'What is the best first step when a guest says “I like something refreshing”?',a:['Ask a short follow-up about flavor or base preference','Immediately pour the strongest drink','Use technical jargon','Assume they want a gin martini'],c:0,why:'One curious question makes the recommendation personal and welcoming.'},
{q:'What is one reliable way to learn a free-pour count?',a:['Assume each count is exactly 30 ml','Calibrate with a jigger or scale and repeat','Use different bottles each time','Count faster under pressure'],c:1,why:'Flow varies by spout, bottle and liquid; practice and verify the pour.'},
{q:'Which beer ingredient contributes bitterness and many aromas?',a:['Hops','Water only','Yeast only','Glass shape'],c:0,why:'Hops contribute bitterness, flavor and aroma; timing and varieties matter.'},
{q:'What is the first step in inventory control?',a:['A consistent item list, units and count routine','Changing par daily by instinct','Counting only premium bottles','Ignoring comps and waste'],c:0,why:'Clear units and repeatable counts make usage and variance meaningful.'},
{q:'A cocktail tastes flat. Which careful test could help?',a:['Tiny acid or bitters adjustment, one variable at a time','Add a full ounce of sugar immediately','Warm it up','Add more garnish only'],c:0,why:'Small controlled adjustments reveal whether it needs lift or structure.'},
{q:'Which grape is commonly associated with Barolo?',a:['Nebbiolo','Riesling','Sauvignon Blanc','Pinot Gris'],c:0,why:'Barolo and Barbaresco in Piedmont are made from Nebbiolo.'},
{q:'What is the purpose of double straining?',a:['Catch fine ice chips and solids','Increase alcohol','Add sweetness','Preserve carbonation'],c:0,why:'A fine strainer catches small solids after the main strainer.'},
{q:'What should you do if a guest seems visibly intoxicated?',a:['Follow local law and venue policy; stop service and seek support','Offer a double','Ignore it','Ask them to drink water then continue service'],c:0,why:'Guest safety and legal obligations come first; follow policy and involve a manager.'}
];
function gamesPage(root){root.innerHTML=`<div class="content-intro"><div class="eyebrow">RETRIEVAL PRACTICE · LOW PRESSURE</div><h1 class="display">Train your bar brain.</h1><p class="lead">Short practice beats passive scrolling. Play a 10-question round, then review why each answer matters.</p></div><div class="grid-2"><article class="topic-card"><span class="tag gold">10 QUESTIONS · SHUFFLED</span><h3 style="margin-top:12px">The Bartender's Bench</h3><p>Technique, spirits, service, wine, beer, inventory and balance.</p><button class="btn" style="margin-top:14px" onclick="startQuiz()">Start a round →</button><div class="lesson-block" style="margin-top:15px"><b>Personal best</b><p>${store.quizBest||'—'} / 10 · saved only on this device</p></div></article><article class="topic-card"><span class="tag">FLAVOR THINKING</span><h3 style="margin-top:12px">Pairing prompt</h3><p>Get a spirit-and-food match. Explain it using echo, contrast or bridge before revealing the teaching note.</p><button class="btn btn-outline" style="margin-top:14px" onclick="pairGame()">Draw a prompt →</button><div id="pair-prompt" class="lesson-block" style="margin-top:15px">Your prompt will appear here.</div></article></div><div class="section-head"><div><h2>Practice ideas</h2><p>Bring the game into a safe, thoughtful tasting session.</p></div></div><div class="grid-3"><article class="card"><h3>Blind aroma trio</h3><p>Smell citrus peel, herb and spice separately. Describe without naming; then compare with a gin botanical list.</p></article><article class="card"><h3>Balance ladder</h3><p>Make tiny measured variations to one sour: change acid, sweetness and dilution separately. Record what shifted.</p></article><article class="card"><h3>Guest-language drill</h3><p>Explain one drink in 15 seconds without jargon: base, flavor, strength impression and one choice for the guest.</p></article></div><div id="quiz-area"></div>`}
function startQuiz(){gameState.quizQuestions=[...quizBank].sort(()=>Math.random()-.5).slice(0,10);gameState.quizIndex=0;gameState.quizScore=0;gameState.quizLocked=false;renderQuiz()}
function renderQuiz(){let area=$('#quiz-area');if(!area)return;let i=gameState.quizIndex,qs=gameState.quizQuestions;if(i>=qs.length){let score=gameState.quizScore;store.quizBest=Math.max(store.quizBest,score);save();area.innerHTML=`<div class="detail-section" style="margin-top:18px"><div class="eyebrow">ROUND COMPLETE</div><h2 style="font:600 28px 'Playfair Display'">${score>=8?'Sharp work. Keep tasting.':score>=5?'Good foundation. Review and retry.':'Every great bartender is always learning.'}</h2><p>You scored <b>${score}/10</b>. Personal best: ${store.quizBest}/10.</p><button class="btn" onclick="startQuiz()">Play again</button></div>`;return}let q=qs[i];area.innerHTML=`<div class="detail-section" style="margin-top:18px"><div class="eyebrow">QUESTION ${i+1} OF ${qs.length} · SCORE ${gameState.quizScore}</div><h2 style="font:600 23px 'Playfair Display'">${q.q}</h2>${q.a.map((x,n)=>`<button class="quiz-choice" data-answer="${n}" ${gameState.quizLocked?'disabled':''}>${String.fromCharCode(65+n)} · ${x}</button>`).join('')}<div id="quiz-feedback"></div></div>`;$$('[data-answer]').forEach(b=>b.onclick=()=>answerQuiz(+b.dataset.answer))}
function answerQuiz(n){if(gameState.quizLocked)return;gameState.quizLocked=true;let q=gameState.quizQuestions[gameState.quizIndex],ok=n===q.c;if(ok)gameState.quizScore++;$$('[data-answer]').forEach(b=>{b.disabled=true;if(+b.dataset.answer===q.c)b.classList.add('correct');if(+b.dataset.answer===n&&!ok)b.classList.add('wrong')});$('#quiz-feedback').innerHTML=`<div class="lesson-block"><b>${ok?'Correct.':'Not quite.'}</b><p>${q.why}</p></div><button class="btn btn-small" onclick="nextQuiz()">${gameState.quizIndex===9?'See result':'Next question →'}</button>`}
function nextQuiz(){gameState.quizIndex++;gameState.quizLocked=false;renderQuiz()}
function pairGame(){let p=pairings[Math.floor(Math.random()*pairings.length)];$('#pair-prompt').innerHTML=`<b>${p.spirit} + ${p.food}</b><p>Before revealing: would you use echo, contrast or bridge?</p><button class="link-btn" onclick="this.nextElementSibling.style.display='block'">Reveal a reason +</button><p style="display:none">${p.why}<br><br><b>Technique:</b> ${p.tech}</p>`}
function assistantPage(root){root.innerHTML=`<div class="content-intro"><div class="eyebrow">LOCAL RULE-BASED STUDY PROMPT</div><h1 class="display">Ask, taste, learn.</h1><p class="lead">A local rule-based study prompt that recognizes a limited set of drink, spirit, service and costing topics. It is not generative AI, live search or a substitute for the full guide, current law or venue procedures.</p></div><div class="grid-2"><article class="topic-card"><div><span class="tag gold">LOCAL KNOWLEDGE MODE</span><h3 style="margin-top:12px">Bar mentor</h3></div><div class="chat-box" id="chat-box"><div class="chat-msg bot">Hello. I can help with recipe structure, spirit production, service practice, pairing ideas and bar math. Answers come from the educational content stored in this page.</div></div><form class="chat-form" id="chat-form"><input id="chat-input" aria-label="Ask the local rule-based study helper" placeholder="Ask about a cocktail, a technique, a guest…" autocomplete="off" maxlength="500"><button class="btn">Ask</button></form><div class="ai-note">Privacy: your question stays in this browser and is not sent to a service. Learning notes are stored in this browser’s localStorage; export a backup before clearing browser data.</div></article><article class="topic-card"><h3>Try asking</h3><div class="pill-row">${['How do I balance a Daiquiri?','Explain bourbon vs Scotch','Help me make a low-sugar gin highball','What should I ask a guest who wants something refreshing?','Suggest a beer with momo','How do I calculate pour cost?'].map(q=>`<button class="filter-chip" onclick="document.getElementById('chat-input').value='${q}';document.getElementById('chat-input').focus()">${q}</button>`).join('')}</div><div class="lesson-block" style="margin-top:16px"><b>Good mentor prompts include context</b><p>What ingredients, tools, guest preferences, cost target and service constraints do you have? The more context you add, the more practical the answer.</p></div><div class="callout">This is an educational aid, not legal, medical or food-safety advice. Confirm regulations, allergen controls and responsible-service decisions with local authorities and venue policy.</div><h3>Learning sources</h3><p>Content is original study material informed by the references listed in the project’s Sources and bibliography notes. Historical claims are qualified where disputed.</p><ul style="font-size:11px;line-height:1.9;color:#6e7971"><li><a href="https://iba-world.com/iba-cocktails/" target="_blank" rel="noreferrer">International Bartenders Association · IBA Cocktails</a></li><li><a href="https://www.thecocktaildb.com/" target="_blank" rel="noreferrer">TheCocktailDB · selected recipe references</a></li><li><a href="https://distilledspirits.org/education-partners/" target="_blank" rel="noreferrer">Distilled Spirits Council · Spirits education</a></li><li><a href="https://www.ttb.gov/regulated-commodities/beverage-alcohol/distilled-spirits" target="_blank" rel="noreferrer">US TTB · Distilled spirits regulations</a></li><li><a href="https://winefolly.com/wine-glossary/" target="_blank" rel="noreferrer">Wine Folly · Wine glossary</a></li><li><a href="https://www.brewersassociation.org/educational-publications/american-craft-beer-guide/" target="_blank" rel="noreferrer">Brewers Association · American Craft Beer Guide</a></li></ul></article></div>`;$('#chat-form').onsubmit=e=>{e.preventDefault();sendChat()}}
function localAnswer(q){let s=q.toLowerCase();let out=[];let add=(title,text)=>out.push(`${title}\n${text}`);let c=cocktails.find(x=>s.includes(x.name.toLowerCase())||x.name.toLowerCase().includes(s)&&s.length>4);if(c)add(`${c.name} · ${c.family}`,`Spec: ${c.spec}. Method: ${c.method} Taste: ${c.taste} Origin note: ${c.history}`);let spirit=spiritLessons.find(x=>s.includes(x.name.toLowerCase().split(' ')[0])|| (x.key==='whiskey'&&/scotch|bourbon|rye|irish whiskey/.test(s)));if(spirit)add(spirit.name,`${spirit.summary} Production: ${spirit.production} Taste: ${spirit.taste} Styles: ${spirit.types}`);let l=liqueurs.find(x=>s.includes(x.name.toLowerCase())|| (x.name.toLowerCase().includes(s)&&s.length>4));if(l)add(l.name,`${l.category}: ${l.taste} Try: ${l.use}`);let pair=pairings.find(x=>s.includes(x.spirit.toLowerCase())&&s.includes(x.food.toLowerCase().split(' ')[0]));if(pair)add('Pairing idea',`${pair.spirit} with ${pair.food}: ${pair.why} ${pair.tech}`);if(/cost|price|pour cost|margin/.test(s))add('Costing',`Cost per pour = bottle cost ÷ bottle volume × pour volume. Add other ingredient costs. Target price = total drink cost ÷ target beverage-cost fraction. See Build a signature for calculator.`);if(/free.?pour|count/.test(s))add('Free-pour practice','A count is not a fixed volume. Calibrate the spout and bottle with a jigger or scale; repeat, log error, and follow venue policy.');if(/guest|hospitality|service|difficult|intox/.test(s))add('Hospitality','Ask one open question about flavor, base, sweetness or strength. Listen, repeat the order and offer choices. For safety or intoxication, stop service as required by local law and venue policy, involve a manager and prioritize guest safety.');if(/wine|grape|beer|lager|ipa|stout/.test(s))add('Wine & beer','Explore the Wine & Beer module for winemaking, grape notes, regions, beer brewing and style profiles.');if(!out.length)add('A good next step','Try a named drink, spirit or technique—or open the Spirits Atlas, Pairing Studio, Service guide or Games. I am using the local study guide, so answers are limited to the educational content stored in this page.');return out.join('\n\n')}
function sendChat(){let input=$('#chat-input'),text=input.value.trim();if(!text)return;let box=$('#chat-box');const addMessage=(kind,value)=>{let node=document.createElement('div');node.className=`chat-msg ${kind}`;node.textContent=value;box.append(node)};addMessage('user',text);input.value='';let answer=localAnswer(text);addMessage('bot',answer);box.scrollTop=box.scrollHeight}
function openGlobalSearch(){cocktailQuery='';cocktailFilter='All';go('cocktails');setTimeout(()=>$('#cocktail-search')?.focus(),30)}
function markComplete(id){if(!(spiritLessons.some(s=>s.key===id)||/^svc\d+$/.test(id)&&Number(id.slice(3))<serviceTopics.length))return;if(!store.completed.includes(id))store.completed.push(id);else store.completed=store.completed.filter(x=>x!==id);if(save())toast(store.completed.includes(id)?'Marked as studied':'Removed from study list');render()}
function exportData(){let blob=new Blob([JSON.stringify({product:'Pourfolio',exported:new Date().toISOString(),learning:{...store,settings:{}}},null,2)],{type:'application/json'});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='pourfolio-learning-data.json';a.click();URL.revokeObjectURL(a.href);toast('Learning data exported')}
